cat > src/lang/types.ts <<'EOF'
export type Mode = "2d" | "3d";
export type Vec3 = [number, number, number];

export interface Segment {
  from: Vec3;
  to: Vec3;
  color: string;
  width: number;
}

export interface LogoError {
  message: string;
  line: number;
  column: number;
}

export interface RunResult {
  segments: Segment[];
  error: LogoError | null;
}

/** Thrown internally; converted to a LogoError at the module's interface. */
export class LogoFailure extends Error {
  constructor(
    message: string,
    public line: number,
    public column: number,
  ) {
    super(message);
  }
  toError(): LogoError {
    return { message: this.message, line: this.line, column: this.column };
  }
}
EOF
cat > src/lang/lexer.ts <<'EOF'
import { LogoFailure } from "./types";

export type TokenKind = "number" | "word";

export interface Token {
  kind: TokenKind;
  text: string;
  /** Lower-cased word text, or the numeric value for numbers. */
  value: string | number;
  line: number;
  column: number;
}

const isSpace = (c: string) => c === " " || c === "\t" || c === "\r" || c === "\n";
const isDigit = (c: string) => c >= "0" && c <= "9";
const isWordChar = (c: string) => /[\p{L}\p{N}_]/u.test(c);

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let column = 1;
  const advance = () => {
    if (source[i] === "\n") {
      line++;
      column = 1;
    } else column++;
    i++;
  };
  while (i < source.length) {
