import type { Token } from "./lexer";
import { LogoFailure } from "./types";

export interface NumExpr {
  kind: "num";
  value: number;
  token: Token;
}

export type Expr = NumExpr;

export type Stmt =
  | { kind: "move"; sign: 1 | -1; arg: Expr; token: Token }
  | { kind: "turn"; sign: 1 | -1; arg: Expr; token: Token }
  | { kind: "color"; color: string; token: Token }
  | { kind: "width"; arg: Expr; token: Token }
  | { kind: "repeat"; count: Expr; body: Stmt[]; token: Token; close: Token };

export interface Program {
  body: Stmt[];
}

type CommandName = "np" | "ws" | "pw" | "lw" | "kolor" | "grubosc" | "powtorz";

const ALIASES: Record<string, CommandName> = {};
const alias = (name: CommandName, ...words: string[]) => {
  for (const w of [name, ...words]) ALIASES[w] = name;
};
alias("np", "naprzod", "naprzód", "fd", "forward");
alias("ws", "wstecz", "bk", "back");
alias("pw", "prawo", "rt", "right");
alias("lw", "lewo", "lt", "left");
alias("kolor", "color");
alias("grubosc", "grubość", "width");
alias("powtorz", "powtórz", "repeat");

const fail = (tok: Token, message: string): never => {
  throw new LogoFailure(message, tok.line, tok.column);
};

export function parse(tokens: Token[]): Program {
  let pos = 0;
  const peek = () => tokens[pos];

  function parseExpr(): Expr {
    const tok = tokens[pos++];
    return { kind: "num", value: tok.value as number, token: tok };
  }

  function parseBlock(): { body: Stmt[]; close: Token } {
    pos++; // [
    const body: Stmt[] = [];
    while (peek() && !(peek().kind === "punct" && peek().value === "]")) body.push(parseStmt());
    const close = tokens[pos++];
    return { body, close };
  }

  function parseStmt(): Stmt {
    const tok = tokens[pos++];
    const cmd = tok.kind === "word" ? ALIASES[tok.value as string] : undefined;
    switch (cmd) {
      case "np":
      case "ws":
        return { kind: "move", sign: cmd === "np" ? 1 : -1, arg: parseExpr(), token: tok };
      case "pw":
      case "lw":
        return { kind: "turn", sign: cmd === "pw" ? 1 : -1, arg: parseExpr(), token: tok };
      case "kolor": {
        const c = tokens[pos++];
        return { kind: "color", color: (c.value as string).toLowerCase(), token: tok };
      }
      case "grubosc":
        return { kind: "width", arg: parseExpr(), token: tok };
      case "powtorz": {
        const count = parseExpr();
        const { body, close } = parseBlock();
        return { kind: "repeat", count, body, token: tok, close };
      }
    }
    return fail(tok, `Nieznane polecenie „${tok.text}”.`);
  }

  const body: Stmt[] = [];
  while (pos < tokens.length) body.push(parseStmt());
  return { body };
}
