import type { Expr, Program, Stmt } from "./parser";
import type { Segment, Vec3 } from "./types";

const add = (a: Vec3, b: Vec3, k: number): Vec3 => [a[0] + b[0] * k, a[1] + b[1] * k, a[2] + b[2] * k];
/** a·cos + b·sin */
const mix = (a: Vec3, b: Vec3, c: number, s: number): Vec3 => [
  a[0] * c + b[0] * s,
  a[1] * c + b[1] * s,
  a[2] * c + b[2] * s,
];

/** sin/cos in degrees, exact at multiples of 90° so right-angle figures close exactly. */
export function sinCosDeg(deg: number): [number, number] {
  const a = ((deg % 360) + 360) % 360;
  if (a === 0) return [0, 1];
  if (a === 90) return [1, 0];
  if (a === 180) return [0, -1];
  if (a === 270) return [-1, 0];
  const rad = (a * Math.PI) / 180;
  return [Math.sin(rad), Math.cos(rad)];
}

export class Machine {
  segments: Segment[] = [];
  pos: Vec3 = [0, 0, 0];
  heading: Vec3 = [0, 1, 0];
  right: Vec3 = [1, 0, 0];
  up: Vec3 = [0, 0, 1];
  color = "#16866a";
  width = 3;

  constructor(private program: Program) {}

  runAll() {
    this.execBlock(this.program.body);
  }

  private execBlock(body: Stmt[]) {
    for (const stmt of body) this.exec(stmt);
  }

  private eval(expr: Expr): number {
    return expr.value;
  }

  private exec(stmt: Stmt) {
    switch (stmt.kind) {
      case "move": {
        const to = add(this.pos, this.heading, this.eval(stmt.arg) * stmt.sign);
        this.segments.push({ from: this.pos, to, color: this.color, width: this.width });
        this.pos = to;
        return;
      }
      case "turn": {
        const [s, c] = sinCosDeg(this.eval(stmt.arg) * stmt.sign);
        const h = this.heading;
        this.heading = mix(h, this.right, c, s);
        this.right = mix(this.right, h, c, -s);
        return;
      }
      case "color":
        this.color = stmt.color;
        return;
      case "width":
        this.width = this.eval(stmt.arg);
        return;
      case "repeat": {
        const n = this.eval(stmt.count);
        for (let i = 1; i <= n; i++) this.execBlock(stmt.body);
        return;
      }
    }
  }
}
