describe("brackets and parentheses", () => {
  test("an unclosed [ is reported at the bracket", () => {
    const error = errorOf("powtorz 4 [\n  np 10\n  pw 90");
    expect(error).toMatchObject({ line: 1, column: 11 });
    expect(error.message).toContain("]");
