    expect(errorOf("np 10 ]\nnp 5")).toMatchObject({ line: 1, column: 7 });
  });

  test("an unclosed ( is reported at the parenthesis, a stray ) at itself", () => {
    expect(errorOf("np (3 + 4")).toMatchObject({ line: 1, column: 4 });
    expect(errorOf("np (3 + 4 pw 9")).toMatchObject({ line: 1, column: 4 });
    expect(errorOf("np 3 + 4)")).toMatchObject({ line: 1, column: 9 });
  });

