cat > src/lang/parser.ts <<'EOF'
import { countProblem, EvalProblem, evaluate, widthProblem } from "./evaluate";
import type { Token } from "./lexer";
import { LogoFailure } from "./types";

export type Expr =
  | { kind: "num"; value: number; token: Token }
  | { kind: "neg"; operand: Expr; token: Token }
  | { kind: "var"; name: string; token: Token }
  | { kind: "repcount"; token: Token }
  | { kind: "bin"; op: "+" | "-" | "*" | "/"; left: Expr; right: Expr; token: Token };

/** A command argument: the expression, its first token (where its errors are reported), and whether it uses no names. */
export interface Arg {
  expr: Expr;
  start: Token;
  constant: boolean;
}

export type Comparison = "<" | ">" | "=" | "<=" | ">=" | "<>";

export interface Block {
  body: Stmt[];
  close: Token;
}

export type Stmt =
  | { kind: "move"; sign: 1 | -1; arg: Arg; token: Token }
  | { kind: "turn"; sign: 1 | -1; arg: Arg; token: Token }
  | { kind: "pen"; down: boolean; token: Token }
  | { kind: "let"; name: string; arg: Arg; token: Token }
  | { kind: "color"; color: string; token: Token }
  | { kind: "width"; arg: Arg; token: Token }
  | { kind: "if"; left: Arg; op: Comparison; right: Arg; then: Block; else: Block | null; token: Token }
  | { kind: "repeat"; count: Arg; body: Stmt[]; token: Token; close: Token }
  | { kind: "call"; name: string; args: Arg[]; token: Token };

export interface Procedure {
  name: string;
  params: string[];
  body: Stmt[];
  token: Token;
  /** The `już` token that ends the definition. */
  end: Token;
}

export interface Program {
  body: Stmt[];
  procedures: Map<string, Procedure>;
}

type CommandName =
  | "np"
  | "ws"
  | "pw"
  | "lw"
  | "pod"
  | "opu"
  | "kolor"
  | "grubosc"
  | "powtorz"
  | "niech"
  | "jesli"
  | "jezeli"
  | "oto"
  | "juz";

const ALIASES: Record<string, CommandName> = {};
const alias = (name: CommandName, ...words: string[]) => {
  for (const w of [name, ...words]) ALIASES[w] = name;
};
alias("np", "naprzod", "naprzód", "fd", "forward");
alias("ws", "wstecz", "bk", "back");
alias("pw", "prawo", "rt", "right");
alias("lw", "lewo", "lt", "left");
alias("pod", "podnies", "podnieś", "pu", "penup");
alias("opu", "opusc", "opuść", "pd", "pendown");
alias("kolor", "color");
alias("grubosc", "grubość", "width");
alias("powtorz", "powtórz", "repeat");
alias("niech", "let");
alias("jesli", "jeśli", "if");
alias("jezeli", "jeżeli", "ifelse");
alias("oto", "to");
alias("juz", "już", "end");

const REPCOUNT = new Set(["nrpowt", "repcount"]);

const isCommandWord = (word: string) => word in ALIASES || REPCOUNT.has(word);
const commandOf = (tok: Token | undefined): CommandName | undefined =>
  tok && tok.kind === "word" && !tok.colon ? ALIASES[tok.value as string] : undefined;

export const plural = (n: number, one: string, few: string, many: string) => {
  if (n === 1) return `${n} ${one}`;
  const d = n % 10;
  const dd = n % 100;
  return `${n} ${d >= 2 && d <= 4 && !(dd >= 12 && dd <= 14) ? few : many}`;
};

const fail = (tok: Token, message: string): never => {
  throw new LogoFailure(message, tok.line, tok.column);
};

/** What pass A learns about one definition: enough to parse calls and names anywhere in the program. */
interface Header {
  oto: number;
  name: string;
  params: string[];
  /** Index of the first body token. */
  bodyStart: number;
  /** Index of the `już` token, or -1 when it is missing. */
  end: number;
  locals: Set<string>;
}

const firstOnLine = (tokens: Token[], i: number) => i === 0 || tokens[i - 1].line < tokens[i].line;
const aloneOnLine = (tokens: Token[], i: number) =>
  firstOnLine(tokens, i) && (i + 1 >= tokens.length || tokens[i + 1].line > tokens[i].line);

/** Pass A: find definitions and declared names, leniently; pass B reports problems in source order. */
function scan(tokens: Token[]) {
  const headers: Header[] = [];
  const globals = new Set<string>();
  const collectLets = (from: number, to: number, into: Set<string>) => {
    for (let i = from; i + 1 < to; i++)
      if (commandOf(tokens[i]) === "niech" && tokens[i + 1].kind === "word") into.add(tokens[i + 1].value as string);
  };
  let depth = 0;
  let topFrom = 0;
  for (let i = 0; i < tokens.length; i++) {
    const tok = tokens[i];
    if (tok.kind === "punct" && tok.value === "[") depth++;
    else if (tok.kind === "punct" && tok.value === "]") depth = Math.max(0, depth - 1);
    if (!(commandOf(tok) === "oto" && depth === 0 && firstOnLine(tokens, i))) continue;
    collectLets(topFrom, i, globals);
    let j = i + 1;
    while (j < tokens.length && tokens[j].line === tok.line) j++;
    const headerTokens = tokens.slice(i + 1, j);
    const name = headerTokens[0]?.kind === "word" ? (headerTokens[0].value as string) : "";
    const params = headerTokens
      .slice(1)
      .filter((t) => t.kind === "word" && t.value !== "ma:" && t.value !== "ma")
      .map((t) => t.value as string);
    let end = -1;
    let k = j;
    for (; k < tokens.length; k++) {
      if (commandOf(tokens[k]) === "juz" && aloneOnLine(tokens, k)) {
        end = k;
        break;
      }
      if (commandOf(tokens[k]) === "oto" && firstOnLine(tokens, k)) break;
    }
    const locals = new Set<string>();
    collectLets(j, end === -1 ? k : end, locals);
    headers.push({ oto: i, name, params, bodyStart: j, end, locals });
    if (end === -1) {
      i = k - 1;
      topFrom = k;
    } else {
      i = end;
      topFrom = end + 1;
    }
  }
  collectLets(topFrom, tokens.length, globals);
  return { headers, globals };
}

export function parse(tokens: Token[]): Program {
  const { headers, globals } = scan(tokens);
  const arity = new Map<string, Header>();
  for (const h of headers) if (h.name && !arity.has(h.name)) arity.set(h.name, h);
  const procedures = new Map<string, Procedure>();

  let pos = 0;
  /** Parsing stops at this index: the end of the program or the `już` of the current definition. */
  let limit = tokens.length;
  const atEnd = () => pos >= limit;
  const peek = (): Token | undefined => tokens[pos];

  /** The definition whose body is being parsed, or null at top level. */
  let current: Header | null = null;
  let blockDepth = 0;
  /** Repeats lexically enclosing the current position (within the current procedure body or top level). */
  let repeatDepth = 0;

  const isPunct = (tok: Token | undefined, ...values: string[]) =>
    !!tok && tok.kind === "punct" && values.includes(tok.value as string);

  /** A binary operator needs whitespace on both sides or on neither side. */
  const binaryAt = (...ops: string[]) => {
    const tok = peek();
    return !atEnd() && isPunct(tok, ...ops) && tok!.spaceBefore === tok!.spaceAfter;
  };

  const isParam = (name: string) => !!current && current.params.includes(name);
  const isDeclared = (name: string) => isParam(name) || !!current?.locals.has(name) || globals.has(name);

  /** The command whose argument is being parsed; used to place and phrase missing-argument errors. */
  let argOwner: { tok: Token; what: string } | null = null;
  let usesNames = false;

  function parseArg(owner: Token, problem?: (v: number) => string | null, what?: string): Arg {
    const saved = [argOwner, usesNames] as const;
    argOwner = { tok: owner, what: what ?? `Brak argumentu polecenia „${owner.text}”` };
    usesNames = false;
    const start = peek()!;
    try {
      const expr = parseExpr();
      const arg = { expr, start, constant: !usesNames };
      if (problem && arg.constant) checkConstant(arg, problem);
      return arg;
    } finally {
      [argOwner, usesNames] = saved;
    }
  }

  /** Literal widths and repeat counts are checked before anything runs; division by zero stays a run-time error. */
  function checkConstant(arg: Arg, problem: (v: number) => string | null) {
    let value: number;
    try {
      value = evaluate(arg.expr, null);
    } catch (e) {
      if (e instanceof EvalProblem) return;
      throw e;
    }
    const message = problem(value);
    if (message) fail(arg.start, message);
  }

  function missing(tok: Token | undefined): never {
    const owner = argOwner!;
    if (!tok) return fail(owner.tok, `${owner.what}: program kończy się za wcześnie.`);
    if (commandOf(tok) || arity.has(tok.value as string))
      return fail(tok, `${owner.what}: znaleziono polecenie „${tok.text}”.`);
    return fail(tok, `${owner.what}: znaleziono „${tok.text}”.`);
  }

  function parseExpr(): Expr {
    let left = parseTerm();
    while (binaryAt("+", "-")) {
      const op = tokens[pos++];
      left = { kind: "bin", op: op.value as "+" | "-", left, right: parseTerm(), token: op };
    }
    return left;
  }

  function parseTerm(): Expr {
    let left = parseUnary();
    while (binaryAt("*", "/")) {
      const op = tokens[pos++];
      left = { kind: "bin", op: op.value as "*" | "/", left, right: parseUnary(), token: op };
    }
    return left;
  }

  function parseUnary(): Expr {
    const tok = peek();
    if (!atEnd() && isPunct(tok, "-", "+")) {
      pos++;
      const operand = parseUnary();
      return tok!.value === "-" ? { kind: "neg", operand, token: tok! } : operand;
    }
    return parsePrimary();
  }

  function parsePrimary(): Expr {
    const tok = peek();
    if (!tok) return missing(tok);
    if (isPunct(tok, "(")) {
      pos++;
      const inner = parseExpr();
      if (atEnd() || !isPunct(peek(), ")")) fail(tok, "Brak nawiasu „)” zamykającego ten nawias.");
      pos++;
      return inner;
    }
    if (tok.kind === "number") {
      pos++;
      return { kind: "num", value: tok.value as number, token: tok };
    }
    if (tok.kind === "word") {
      const name = tok.value as string;
      if (!tok.colon && REPCOUNT.has(name)) {
        if (repeatDepth === 0) return fail(tok, `„${tok.text}” można użyć tylko wewnątrz powtórz [ ... ].`);
        pos++;
        usesNames = true;
        return { kind: "repcount", token: tok };
      }
      if (isParam(name) || (!commandOf(tok) && isDeclared(name))) {
        pos++;
        usesNames = true;
        return { kind: "var", name, token: tok };
      }
      if (!tok.colon && (commandOf(tok) || arity.has(name))) return missing(tok);
      return fail(tok, `Nieznana nazwa „${tok.text}”: to nie jest parametr ani zmienna nadana przez niech.`);
    }
    return missing(tok);
  }

  function parseBlock(owner: Token): Block {
    const open = peek();
    if (atEnd() || !open) return fail(owner, `Polecenie „${owner.text}” wymaga treści w nawiasach [ ].`);
    if (!isPunct(open, "[")) return fail(open, `Oczekiwano „[” z treścią polecenia „${owner.text}”, a znaleziono „${open.text}”.`);
    pos++;
    blockDepth++;
    const body = parseStatements(() => isPunct(peek(), "]"));
    if (atEnd()) return fail(open, "Brak nawiasu „]” zamykającego ten nawias.");
    blockDepth--;
    const close = tokens[pos++];
    return { body, close };
  }

  function parseStatements(stop: () => boolean): Stmt[] {
    const body: Stmt[] = [];
    let previousCall: Header | null = null;
    while (!atEnd() && !stop()) {
      const tok = peek()!;
      if (previousCall && !commandOf(tok) && !arity.has(tok.value as string) && !isPunct(tok, "[", "]")) {
        fail(
          tok,
          `Za dużo argumentów: procedura „${previousCall.name}” przyjmuje ${plural(previousCall.params.length, "argument", "argumenty", "argumentów")}.`,
        );
      }
      if (commandOf(tok) === "oto") {
        parseDefinition();
        previousCall = null;
        continue;
      }
      const stmt = parseStmt();
      previousCall = stmt.kind === "call" ? arity.get(stmt.name)! : null;
      body.push(stmt);
    }
    return body;
  }

  function parseDefinition() {
    const tok = tokens[pos];
    if (current) {
      return fail(
        tok,
        `Nie można zdefiniować procedury wewnątrz innej procedury. Czy brakuje „już” kończącego „${current.name}”?`,
      );
    }
    if (blockDepth > 0) return fail(tok, "Procedury definiuje się tylko na najwyższym poziomie, nie wewnątrz [ ].");
    if (!firstOnLine(tokens, pos)) return fail(tok, `Definicja „${tok.text}” musi zaczynać się na początku wiersza.`);
    const header = headers.find((h) => h.oto === pos)!;
    const nameTok = tokens[pos + 1];
    if (!nameTok || nameTok.line !== tok.line) return fail(tok, `Po „${tok.text}” podaj nazwę procedury w tym samym wierszu.`);
    if (nameTok.kind !== "word" || nameTok.colon) return fail(nameTok, `„${nameTok.text}” nie może być nazwą procedury.`);
    if (isCommandWord(nameTok.value as string))
      return fail(nameTok, `„${nameTok.text}” to polecenie języka; wybierz inną nazwę procedury.`);
    const name = nameTok.value as string;
    const earlier = procedures.get(name);
    if (earlier) return fail(nameTok, `Procedura „${nameTok.text}” jest już zdefiniowana w wierszu ${earlier.token.line}.`);
    const params = parseParams(tokens.slice(pos + 2, header.bodyStart));
    if (header.end === -1) return fail(tok, `Brak „już” kończącego procedurę „${nameTok.text}”.`);

    pos = header.bodyStart;
    limit = header.end;
    current = header;
    repeatDepth = 0;
    const body = parseStatements(() => false);
    current = null;
    limit = tokens.length;
    pos = header.end + 1;
    procedures.set(name, { name, params, body, token: tok, end: tokens[header.end] });
  }

  function parseParams(list: Token[]): string[] {
    const params: string[] = [];
    const add = (t: Token) => {
      const name = t.value as string;
      if (t.kind !== "word" || isCommandWord(name) || name === "ma:")
        fail(t, `„${t.text}” nie może być nazwą parametru.`);
      if (params.includes(name)) fail(t, `Parametr „${t.text}” powtarza się.`);
      params.push(name);
    };
    if (list.length === 0) return params;
    const first = list[0];
    if (first.kind === "word" && !first.colon && (first.value === "ma:" || first.value === "ma")) {
      const rest = list.slice(1);
      if (rest.length === 0) fail(first, "Po „ma:” podaj nazwy parametrów oddzielone przecinkami.");
      rest.forEach((t, i) => {
        if (i % 2 === 1) {
          if (!isPunct(t, ",")) fail(t, `Parametry oddziel przecinkami; znaleziono „${t.text}”.`);
        } else add(t);
      });
      if (isPunct(rest[rest.length - 1], ",")) fail(rest[rest.length - 1], "Po przecinku brakuje nazwy parametru.");
      return params;
    }
    for (const t of list) {
      if (t.kind !== "word" || !t.colon) fail(t, `Oczekiwano parametru w postaci „ma: nazwa” albo „:nazwa”, a znaleziono „${t.text}”.`);
      add(t);
    }
    return params;
  }

  function parseStmt(): Stmt {
    const tok = tokens[pos++];
    const cmd = commandOf(tok);
    switch (cmd) {
      case "np":
      case "ws":
        return { kind: "move", sign: cmd === "np" ? 1 : -1, arg: parseArg(tok), token: tok };
      case "pw":
      case "lw":
        return { kind: "turn", sign: cmd === "pw" ? 1 : -1, arg: parseArg(tok), token: tok };
      case "pod":
      case "opu":
        return { kind: "pen", down: cmd === "opu", token: tok };
      case "kolor": {
        const c = atEnd() ? undefined : tokens[pos];
        if (!c) return fail(tok, 'Polecenie „kolor” wymaga koloru, np. kolor "#16866a".');
        if (c.kind !== "string" || !/^#[0-9a-f]{6}$/i.test(c.value as string))
          return fail(c, `Nieprawidłowy kolor „${c.text}”: podaj sześć cyfr szesnastkowych w cudzysłowie, np. "#16866a".`);
        pos++;
        return { kind: "color", color: (c.value as string).toLowerCase(), token: tok };
      }
      case "grubosc":
        return { kind: "width", arg: parseArg(tok, widthProblem), token: tok };
      case "niech": {
        const nameTok = atEnd() ? undefined : tokens[pos];
        if (!nameTok) return fail(tok, "Polecenie „niech” wymaga nazwy zmiennej i wartości, np. niech bok 50.");
        if (nameTok.kind !== "word") return fail(nameTok, `Oczekiwano nazwy zmiennej, a znaleziono „${nameTok.text}”.`);
        const name = nameTok.value as string;
        if (isCommandWord(name)) return fail(nameTok, `„${nameTok.text}” to polecenie; nie może być nazwą zmiennej.`);
        if (arity.has(name) && !isParam(name))
          return fail(nameTok, `„${nameTok.text}” to nazwa procedury; nie może być nazwą zmiennej.`);
        pos++;
        return { kind: "let", name, arg: parseArg(tok), token: tok };
      }
      case "jesli":
      case "jezeli": {
        const left = parseArg(tok);
        const opTok = atEnd() ? undefined : peek();
        if (!opTok) return fail(tok, `Polecenie „${tok.text}” wymaga warunku z porównaniem, np. ${tok.text} bok > 10 [...].`);
        if (opTok.kind !== "cmp")
          return fail(opTok, `Oczekiwano porównania (<, >, =, <=, >=, <>), a znaleziono „${opTok.text}”.`);
        pos++;
        const right = parseArg(tok);
        const then = parseBlock(tok);
        const otherwise = cmd === "jezeli" ? parseBlock(tok) : null;
        return { kind: "if", left, op: opTok.value as Comparison, right, then, else: otherwise, token: tok };
      }
      case "powtorz": {
        const count = parseArg(tok, countProblem);
        repeatDepth++;
        const { body, close } = parseBlock(tok);
        repeatDepth--;
        return { kind: "repeat", count, body, token: tok, close };
      }
      case "juz":
        if (aloneOnLine(tokens, pos - 1)) return fail(tok, `„${tok.text}” bez odpowiadającego mu „oto”.`);
        return fail(tok, `„${tok.text}” kończy definicję procedury i musi stać sam w osobnym wierszu.`);
    }
    if (tok.kind === "word" && !tok.colon) {
      const header = arity.get(tok.value as string);
      if (header) return parseCall(tok, header);
      if (isDeclared(tok.value as string) || REPCOUNT.has(tok.value as string))
        return fail(tok, `Nieoczekiwana wartość „${tok.text}”: oczekiwano polecenia.`);
      return fail(tok, `Nieznane polecenie „${tok.text}”.`);
    }
    if (isPunct(tok, "]")) return fail(tok, "Nadmiarowy nawias „]”: nie zamyka żadnego „[”.");
    return fail(tok, `Nieoczekiwane „${tok.text}”: oczekiwano polecenia.`);
  }

  function parseCall(tok: Token, header: Header): Stmt {
    const n = header.params.length;
    const args: Arg[] = [];
    for (let i = 0; i < n; i++) {
      args.push(
        parseArg(tok, undefined, `Procedura „${tok.text}” wymaga ${plural(n, "argumentu", "argumentów", "argumentów")}, podano ${i}`),
      );
    }
    return { kind: "call", name: header.name, args, token: tok };
  }

  const body = parseStatements(() => false);
  return { body, procedures };
}
