export interface Arg {
  expr: Expr;
  start: Token;
  constant: boolean;
}

export type Comparison = "<" | ">" | "=" | "<=" | ">=" | "<>";

export interface Block {
  body: Stmt[];
  close: Token;
}

export type Stmt =
  | { kind: "move"; sign: 1 | -1; arg: Arg; token: Token }
  | { kind: "turn"; sign: 1 | -1; arg: Arg; token: Token }
  | { kind: "pen"; down: boolean; token: Token }
  | { kind: "let"; name: string; arg: Arg; token: Token }
  | { kind: "color"; color: string; token: Token }
  | { kind: "width"; arg: Arg; token: Token }
