    if (header.end === -1) return fail(tok, `Brak „już” kończącego procedurę „${nameTok.text}”.`);

    pos = header.bodyStart;
    limit = header.end;
    current = header;
    repeatDepth = 0;
    const body = parseStatements(() => false);
    current = null;
    limit = tokens.length;
    pos = header.end + 1;
    procedures.set(name, { name, params, body, token: tok, end: tokens[header.end] });
  }

