      case "pod":
      case "opu":
        return { kind: "pen", down: cmd === "opu", token: tok };
      case "kolor": {
        const c = atEnd() ? undefined : tokens[pos];
        if (!c) return fail(tok, 'Polecenie „kolor” wymaga koloru, np. kolor "#16866a".');
