        pos++;
        return { kind: "let", name, arg: parseArg(tok), token: tok };
      }
      case "jesli":
      case "jezeli": {
        const left = parseArg(tok);
        const opTok = atEnd() ? undefined : peek();
        if (!opTok) return fail(tok, `Polecenie „${tok.text}” wymaga warunku z porównaniem, np. ${tok.text} bok > 10 [...].`);
        if (opTok.kind !== "cmp")
          return fail(opTok, `Oczekiwano porównania (<, >, =, <=, >=, <>), a znaleziono „${opTok.text}”.`);
        pos++;
