      }
      case "powtorz": {
        const count = parseArg(tok, countProblem);
        repeatDepth++;
        const { body, close } = parseBlock(tok);
        repeatDepth--;
        return { kind: "repeat", count, body, token: tok, close };
      }
      case "juz":
        if (aloneOnLine(tokens, pos - 1)) return fail(tok, `„${tok.text}” bez odpowiadającego mu „oto”.`);
