describe("procedure scope", () => {
  test("niech inside a call is local, shadows the global for the rest of the call, and is discarded after", () => {
    expect(distance("niech x 10\noto f\n  np x niech x 1 np x\njuż\nf np x")).toBe(21);
  });

  test("a parameter can be reassigned with niech", () => {
    expect(distance("oto f ma: a\n  niech a a * 2 np a\njuż\nf 5")).toBe(10);
  });

  test("a declared local read before assignment is a run-time error at the argument", () => {
    const result = run("oto f\n  np 1 + y niech y 1\njuż\nnp 5 f", "2d");
    expect(flat(result)).toEqual([[0, 0, 0, 5]]);
    expect(result.error).toMatchObject({ line: 2, column: 6 });
  });

  test("another procedure's locals are not visible: a parse-time error", () => {
    const result = run("oto f\n  niech y 1\njuż\noto g\n  np y\njuż\nnp 5 g", "2d");
    expect(result.segments).toEqual([]);
    expect(result.error).toMatchObject({ line: 5, column: 6 });
  });

  test("a parameter may share its name with a procedure: a call in command position, the value in argument position", () => {
    expect(distance("oto krok\n  np 1\njuż\noto f ma: krok\n  krok np krok\njuż\nf 10")).toBe(11);
  });

  test("a variable may not take a procedure's name", () => {
    expect(errorOf("oto f\n  np 1\njuż\nniech f 5")).toMatchObject({ line: 4, column: 7 });
  });
});
EOF
