describe("definition and call errors", () => {
  const sq = "oto kwadrat ma: bok, kąt\n  powtorz 4 [np bok pw kąt]\njuż\n";

  test("too few arguments: reported at the token found where the argument should start", () => {
    const error = errorOf(sq + "powtorz 2 [kwadrat 50]");
    expect(error).toMatchObject({ line: 4, column: 22 });
    expect(error.message).toMatch(/kwadrat.*2 argument/);
  });

  test("too few arguments at the end of the program: reported at the call", () => {
    expect(errorOf(sq + "np 1 kwadrat 50")).toMatchObject({ line: 4, column: 6 });
  });

  test("too many arguments: reported at the extra value", () => {
    const error = errorOf(sq + "kwadrat 50 90 7");
    expect(error).toMatchObject({ line: 4, column: 15 });
    expect(error.message).toMatch(/za dużo argumentów/i);
  });

  test("a definition inside a repeat body or another procedure is an error at oto", () => {
    expect(errorOf("powtorz 2 [\noto f\n np 1\njuż\n]")).toMatchObject({ line: 2, column: 1 });
    expect(errorOf("oto f\n  np 1\noto g\n  np 2\njuż")).toMatchObject({ line: 3, column: 1 });
  });

  test("a missing już is reported at oto", () => {
    const error = errorOf("np 5\noto f\n  np 1");
    expect(error).toMatchObject({ line: 2, column: 1 });
    expect(error.message).toContain("już");
  });

  test("a name may be defined once", () => {
    expect(errorOf("oto f\n  np 1\njuż\noto F\n  np 2\njuż")).toMatchObject({ line: 4, column: 5 });
  });

  test("już must stand alone on its line", () => {
    expect(errorOf("oto f\n  np 1 już\nf")).toMatchObject({ line: 1, column: 1 });
  });

  test("nrpowt in a procedure body outside any repeat there is a parse error, even if called from a repeat", () => {
    const result = run("oto f\n  np nrpowt\njuż\npowtorz 3 [f]", "2d");
    expect(result.segments).toEqual([]);
    expect(result.error).toMatchObject({ line: 2, column: 6 });
  });

  test("a stray value in command position is reported at the value", () => {
    expect(errorOf("niech a 5\nnp 1 a")).toMatchObject({ line: 2, column: 6 });
    expect(errorOf("np 1 \"#123456\"")).toMatchObject({ line: 1, column: 6 });
  });

  test("an unknown command names the word", () => {
    const error = errorOf("np 10\n  skacz 5");
    expect(error).toMatchObject({ line: 2, column: 3 });
    expect(error.message).toContain("skacz");
  });
});
EOF
