import { describe, expect, test } from "bun:test";
import { EXAMPLES } from "../src/examples";
import { run } from "../src/lang";
import { r } from "./helpers";

const byId = (id: string) => {
  const example = EXAMPLES.find((e) => e.id === id);
  if (!example) throw new Error(`no example ${id}`);
  return example;
};

const result = (id: string) => {
  const e = byId(id);
  const res = run(e.source, e.mode);
  expect(res.error).toBeNull();
  return res;
};

describe("standard programs", () => {
  test("all thirteen ship under their ids, names and modes", () => {
    expect(EXAMPLES.map((e) => [e.id, e.name, e.mode])).toEqual([
      ["kwadrat", "Kwadrat", "2d"],
      ["gwiazda", "Gwiazda", "2d"],
      ["rozeta", "Rozeta", "2d"],
      ["spirala", "Spirala", "2d"],
      ["wielokaty", "Wielokąty", "2d"],
      ["drzewo", "Drzewo", "2d"],
      ["sniezynka", "Śnieżynka", "2d"],
      ["schody", "Schody", "3d"],
      ["szescian", "Sześcian", "3d"],
      ["pierscien", "Pierścień", "3d"],
      ["kula", "Kula", "3d"],
      ["helisa", "Helisa", "3d"],
      ["drzewo3d", "Drzewo 3D", "3d"],
    ]);
  });

  test("stroke counts follow from each program's structure", () => {
    const counts = Object.fromEntries(EXAMPLES.map((e) => [e.id, result(e.id).segments.length]));
    expect(counts).toEqual({
      kwadrat: 4,
      gwiazda: 5,
      rozeta: 48,
      spirala: 90,
      wielokaty: 3 + 4 + 5 + 6 + 7 + 8 + 9,
      drzewo: 255,
      sniezynka: 3 * 4 ** 4,
      schody: 12,
      szescian: 12,
      pierscien: 36,
      kula: 12 * 36,
      helisa: 240,
      // lengths 70, 42, 25.2, 15.12, 9.07 draw; each draws its trunk and three branches.
      drzewo3d: 1 + 3 + 9 + 27 + 81,
    });
  });

  test("gwiazda closes: the fifth stroke ends at the origin", () => {
    const last = result("gwiazda").segments[4].to.map(r);
    expect(last).toEqual([0, 0, 0]);
  });

  test("spirala alternates its two colours and lengthens each side by 2.5", () => {
    const s = result("spirala").segments;
    expect(s.slice(0, 4).map((x) => x.color)).toEqual(["#16866a", "#c1763d", "#16866a", "#c1763d"]);
    const len = (i: number) => r(Math.hypot(s[i].to[0] - s[i].from[0], s[i].to[1] - s[i].from[1]));
    expect([len(0), len(1), len(89)]).toEqual([2.5, 5, 225]);
  });

  test("schody climbs 20 per step to a height of 120, 210 forward", () => {
    const s = result("schody").segments;
    expect(s[11].to.map(r)).toEqual([0, 210, 120]);
  });

  test("szescian's vertices are the corners of a 100-unit cube", () => {
    const pts = new Set(result("szescian").segments.flatMap((x) => [x.from, x.to]).map((p) => p.map(r).join(",")));
    expect([...pts].sort()).toEqual(
      ["0,0,0", "0,100,0", "100,100,0", "100,0,0", "0,0,100", "0,100,100", "100,100,100", "100,0,100"].sort(),
    );
  });

  test("pierscien is a closed circle tilted 30° out of the plane", () => {
    const s = result("pierscien").segments;
    expect(s[35].to.map(r)).toEqual([0, 0, 0]);
    const top = Math.max(...s.map((x) => x.to[2]));
    const reach = Math.max(...s.map((x) => x.to[1]));
    expect(r(top / reach)).toBe(r(Math.tan(Math.PI / 6)));
  });

  test("flat programs draw identical coordinates in 2D and 3D", () => {
    for (const e of EXAMPLES.filter((x) => x.mode === "2d")) {
      expect(run(e.source, "3d")).toEqual(run(e.source, "2d"));
    }
  });

  test("3D programs are rejected in 2D mode", () => {
    for (const id of ["schody", "szescian", "pierscien", "kula", "helisa", "drzewo3d"]) {
      expect(run(byId(id).source, "2d").error).not.toBeNull();
    }
  });
});
EOF
