describe("parse-time limits", () => {
  test("50,000 source characters are allowed; one more is an error at that character", () => {
    expect(run("np 1" + " ".repeat(50000 - 4), "2d").error).toBeNull();
    const result = run("np 1\n" + ";".repeat(50000 - 5) + "x", "2d");
    expect(result.segments).toEqual([]);
    expect(result.error).toMatchObject({ line: 2, column: 49996 });
    expect(result.error!.message).toContain("50");
  });

  test("10,000 tokens are allowed; the next one is an error at that token", () => {
    expect(run("pw 1 ".repeat(5000), "2d").error).toBeNull();
    const error = errorOf("pw 1\n".repeat(5000) + "pod");
    expect(error).toMatchObject({ line: 5001, column: 1 });
  });

  test("operators, parentheses, brackets and commas count as tokens", () => {
    // 2 + 3 tokens per "np (1)" and the rest in "np 1": (2+3)*1999 + 2*2 = 9999, then "pw - 1" adds 3.
    expect(run("np (1) ".repeat(1999) + "np 1 np 1", "2d").error).toBeNull();
    expect(errorOf("np (1) ".repeat(1999) + "np 1 np 1 pw - 1")).toMatchObject({ line: 1, column: 7 * 1999 + 14 });
  });

  test("brackets nest 32 deep; the 33rd is an error at that bracket", () => {
    const nest = (n: number) => "powtorz 1 [".repeat(n) + "np 1" + "]".repeat(n);
    expect(run(nest(32), "2d").error).toBeNull();
    const result = run(nest(33), "2d");
    expect(result.segments).toEqual([]);
    expect(result.error).toMatchObject({ line: 1, column: 32 * 11 + 11 });
  });

  test("conditional bodies count towards the nesting depth", () => {
    expect(errorOf("jeśli 1 = 1 [".repeat(33) + "np 1" + "]".repeat(33))).toMatchObject({ line: 1, column: 32 * 13 + 13 });
  });
});
EOF
