input.command:
cat >> tests/interpreter.test.ts <<'EOF'

describe("run-time limits", () => {
  test("operations: a repeat costs 1, each iteration its body plus 1 for finishing", () => {
    // 1 + 4999 * (1 + 1) = 9999, then np 1 makes 10,000: allowed.
    expect(run("powtorz 4999 [pw 1] np 1", "2d").error).toBeNull();
    const result = run("powtorz 4999 [pw 1] np 1\nnp 1", "2d");
    expect(result.segments.length).toBe(1);
    expect(result.error).toMatchObject({ line: 2, column: 1 });
    expect(result.error!.message).toContain("10");
  });

  test("operations: a conditional costs 1, a body that runs adds 1 for finishing; a false one adds nothing", () => {
    // 1 + 2499 * (1 if + 1 pw + 1 finish body + 1 finish iteration) = 9997.
    const base = "powtorz 2499 [jeśli 1 = 1 [pw 1]] pw 1 pw 1 jeśli 1 = 2 [np 5]";
    expect(run(base, "2d").error).toBeNull();
    expect(run(base + " pw 1", "2d").error).not.toBeNull();
  });

  test("operations: niech and a call count, and finishing a call adds 1", () => {
    // f costs call + niech + finish = 3; 3333 calls = 9999 plus the repeat (1) and its 3333 finishes.
    const proc = "oto f\n  niech a 1\njuż\n";
    expect(run(proc + "f ".repeat(3333) + "pw 1", "2d").error).toBeNull();
    expect(run(proc + "f ".repeat(3333) + "pw 1 pw 1", "2d").error).not.toBeNull();
  });

  test("33 nested procedure calls exceed the frame limit; what was drawn stays", () => {
    const result = run("oto f ma: n\n  np 1 f n + 1\njuż\nf 1", "2d");
    expect(result.segments.length).toBe(32);
    expect(result.error).toMatchObject({ line: 2, column: 8 });
  });

  test("repeat frames count towards the frame limit, conditional bodies do not", () => {
    const deep = (n: number) => "powtorz 1 [".repeat(n) + "np 1" + "]".repeat(n);
    expect(run(`oto f\n  ${deep(31)}\njuż\nf`, "2d").error).toBeNull();
    expect(run(`oto f\n  ${deep(32)}\njuż\nf`, "2d").error).toMatchObject({ line: 2, column: 31 * 11 + 3 });
    expect(run(`oto f\n  ${deep(16)}\njuż\njeśli 1 = 1 [jeśli 1 = 1 [${deep(15)}]] f`, "2d").error).toBeNull();
  });

  test("every coordinate must stay within ±100,000, pen up or down", () => {
    expect(run("np 100000 ws 200000", "2d").error).toBeNull();
    const result = run("np 50000\npod np 50001", "2d");
    expect(result.segments.length).toBe(1);
    expect(result.error).toMatchObject({ line: 2, column: 5 });
  });
});
EOF
