import type { FrameScheduler } from "../src/runner/controller";

/** A frame scheduler the test advances by hand: time is a system boundary. */
export function fakeClock(frameMs = 16) {
  let now = 0;
  let queue: ((t: number) => void)[] = [];
  const scheduler: FrameScheduler = {
    request(cb) {
      queue.push(cb);
      return () => {
        queue = queue.filter((q) => q !== cb);
      };
    },
    now: () => now,
  };
  return {
    scheduler,
    /** Run one animation frame. */
    frame() {
      now += frameMs;
      const due = queue;
      queue = [];
      for (const cb of due) cb(now);
    },
    frames(n: number) {
      for (let i = 0; i < n; i++) this.frame();
    },
    get pending() {
      return queue.length;
    },
  };
}
