import { countProblem, EvalProblem, evaluate, widthProblem, type Scope } from "./evaluate";
import type { Token } from "./lexer";
import type { Arg, Program, Stmt } from "./parser";
import { LogoFailure, type Segment, type Vec3 } from "./types";

export const MAX_OPERATIONS = 10_000;
export const MAX_FRAMES = 32;
export const MAX_SEGMENTS = 10_000;
export const MAX_COORDINATE = 100_000;

const pl = (n: number) => n.toLocaleString("pl-PL");

const add = (a: Vec3, b: Vec3, k: number): Vec3 => [a[0] + b[0] * k, a[1] + b[1] * k, a[2] + b[2] * k];
/** a·cos + b·sin */
const mix = (a: Vec3, b: Vec3, c: number, s: number): Vec3 => [
  a[0] * c + b[0] * s,
  a[1] * c + b[1] * s,
  a[2] * c + b[2] * s,
];

/** sin/cos in degrees, exact at multiples of 90° so right-angle figures close exactly. */
export function sinCosDeg(deg: number): [number, number] {
  const a = ((deg % 360) + 360) % 360;
  if (a === 0) return [0, 1];
  if (a === 90) return [1, 0];
  if (a === 180) return [0, -1];
  if (a === 270) return [-1, 0];
  const rad = (a * Math.PI) / 180;
  return [Math.sin(rad), Math.cos(rad)];
}

/** Unwinds to the end of the current procedure call, or of the program. */
class StopSignal {}

interface Frame {
  locals: Map<string, number>;
  /** Iteration numbers of the repeats running in this frame, innermost last. */
  repeats: number[];
}

export interface TurtleState {
  pos: Vec3;
  heading: Vec3;
  right: Vec3;
  up: Vec3;
  penDown: boolean;
  color: string;
  width: number;
}

/**
 * Executes a parsed program. `steps()` yields the first token of each statement
 * just before it starts, so a driver can run it all at once or one command at a time.
 */
export class Machine {
  segments: Segment[] = [];
  pos: Vec3 = [0, 0, 0];
  heading: Vec3 = [0, 1, 0];
  right: Vec3 = [1, 0, 0];
  up: Vec3 = [0, 0, 1];
  penDown = true;
  color = "#16866a";
  width = 3;
  operations = 0;
  private frames = 0;
  private globals = new Map<string, number>();
  /** The running procedure call, or the top level (whose variables are the globals). */
  private frame: Frame = { locals: this.globals, repeats: [] };
  private scope: Scope = {
    read: (name) => {
      const v = this.frame.locals.get(name) ?? this.globals.get(name);
      if (v === undefined) throw new EvalProblem(`Zmienna „${name}” nie ma jeszcze wartości.`);
      return v;
    },
    repcount: () => this.frame.repeats[this.frame.repeats.length - 1],
  };

  constructor(private program: Program) {}

  get turtle(): TurtleState {
    return {
      pos: this.pos,
      heading: this.heading,
      right: this.right,
      up: this.up,
      penDown: this.penDown,
      color: this.color,
      width: this.width,
    };
  }

  *steps(): Generator<Token, void, void> {
    try {
      yield* this.execBlock(this.program.body);
    } catch (e) {
      if (!(e instanceof StopSignal)) throw e;
    }
  }

  runAll() {
    const it = this.steps();
    while (!it.next().done);
  }

  private *execBlock(body: Stmt[]): Generator<Token, void, void> {
    for (const stmt of body) {
      yield stmt.token;
      this.tick(stmt.token);
      yield* this.exec(stmt);
    }
  }

  private tick(at: Token) {
    if (++this.operations > MAX_OPERATIONS)
      throw new LogoFailure(`Przekroczono limit ${pl(MAX_OPERATIONS)} wykonanych operacji. Czy program się nie zapętlił?`, at.line, at.column);
  }

  private enterFrame(at: Token) {
    if (this.frames >= MAX_FRAMES)
      throw new LogoFailure(
        `Przekroczono limit ${MAX_FRAMES} jednocześnie aktywnych wywołań procedur i powtórzeń. Czy rekurencja ma warunek końca?`,
        at.line,
        at.column,
      );
    this.frames++;
  }

  private moveTo(to: Vec3, at: Token) {
    if (to.some((c) => Math.abs(c) > MAX_COORDINATE))
      throw new LogoFailure(`Żółw wyszedłby poza obszar rysowania: współrzędne muszą mieścić się w ±${pl(MAX_COORDINATE)}.`, at.line, at.column);
    const from = this.pos;
    const moved = from[0] !== to[0] || from[1] !== to[1] || from[2] !== to[2];
    if (this.penDown && moved) {
      if (this.segments.length >= MAX_SEGMENTS)
        throw new LogoFailure(`Przekroczono limit ${pl(MAX_SEGMENTS)} narysowanych odcinków.`, at.line, at.column);
      this.segments.push({ from, to, color: this.color, width: this.width });
    }
    this.pos = to;
  }

  private eval(arg: Arg, problem?: (v: number) => string | null): number {
    let value: number;
    try {
      value = evaluate(arg.expr, this.scope);
    } catch (e) {
      if (e instanceof EvalProblem) throw new LogoFailure(e.message, arg.start.line, arg.start.column);
      throw e;
    }
    const message = problem?.(value);
    if (message) throw new LogoFailure(message, arg.start.line, arg.start.column);
    return value;
  }

  private *exec(stmt: Stmt): Generator<Token, void, void> {
    switch (stmt.kind) {
      case "move":
        this.moveTo(add(this.pos, this.heading, this.eval(stmt.arg) * stmt.sign), stmt.token);
        return;
      case "turn": {
        const [s, c] = sinCosDeg(this.eval(stmt.arg) * stmt.sign);
        const h = this.heading;
        this.heading = mix(h, this.right, c, s);
        this.right = mix(this.right, h, c, -s);
        return;
      }
      case "pitch": {
        const [s, c] = sinCosDeg(this.eval(stmt.arg) * stmt.sign);
        const h = this.heading;
        this.heading = mix(h, this.up, c, s);
        this.up = mix(this.up, h, c, -s);
        return;
      }
      case "roll": {
        const [s, c] = sinCosDeg(this.eval(stmt.arg) * stmt.sign);
        const u = this.up;
        this.up = mix(u, this.right, c, s);
        this.right = mix(this.right, u, c, -s);
        return;
      }
      case "stop":
        throw new StopSignal();
      case "home":
        this.moveTo([0, 0, 0], stmt.token);
        this.heading = [0, 1, 0];
        this.right = [1, 0, 0];
        this.up = [0, 0, 1];
        return;
      case "clear":
        this.segments = [];
        return;
      case "pen":
        this.penDown = stmt.down;
        return;
      case "let":
        this.frame.locals.set(stmt.name, this.eval(stmt.arg));
        return;
      case "color":
        this.color = stmt.color;
        return;
      case "width":
        this.width = this.eval(stmt.arg, widthProblem);
        return;
      case "call": {
        const proc = this.program.procedures.get(stmt.name)!;
        const locals = new Map<string, number>();
        stmt.args.forEach((arg, i) => locals.set(proc.params[i], this.eval(arg)));
        const outerFrames = this.frames;
        this.enterFrame(stmt.token);
        const saved = this.frame;
        this.frame = { locals, repeats: [] };
        try {
          yield* this.execBlock(proc.body);
        } catch (e) {
          if (!(e instanceof StopSignal)) throw e;
        } finally {
          this.frame = saved;
        }
        // A stop may have unwound repeats inside the call; their frames end with it.
        this.frames = outerFrames;
        this.tick(proc.end);
        return;
      }
      case "if": {
        const a = this.eval(stmt.left);
        const b = this.eval(stmt.right);
        const holds =
          stmt.op === "<" ? a < b : stmt.op === ">" ? a > b : stmt.op === "=" ? a === b : stmt.op === "<=" ? a <= b : stmt.op === ">=" ? a >= b : a !== b;
        const block = holds ? stmt.then : stmt.else;
        if (block) {
          yield* this.execBlock(block.body);
          this.tick(block.close);
        }
        return;
      }
      case "repeat": {
        const n = this.eval(stmt.count, countProblem);
        this.enterFrame(stmt.token);
        const repeats = this.frame.repeats;
        repeats.push(0);
        for (let i = 1; i <= n; i++) {
          repeats[repeats.length - 1] = i;
          yield* this.execBlock(stmt.body);
          this.tick(stmt.close);
        }
        repeats.pop();
        this.frames--;
        return;
      }
    }
  }
}
EOF
cat > src/lang/index.ts <<'EOF'
import { tokenize } from "./lexer";
import { Machine } from "./machine";
import { parse, type Program } from "./parser";
import { LogoFailure, type LogoError, type Mode, type RunResult } from "./types";

export type { Mode, RunResult, Segment, LogoError, Vec3 } from "./types";
export type { TurtleState } from "./machine";
export type { Token } from "./lexer";
export { Machine };

/** Parse a whole program; with an error nothing may be drawn. */
export function compile(source: string, mode: Mode): { program: Program; error: null } | { program: null; error: LogoError } {
  try {
    return { program: parse(tokenize(source), mode), error: null };
  } catch (e) {
    if (e instanceof LogoFailure) return { program: null, error: e.toError() };
    throw e;
  }
}

/** Advance a machine; a LogoFailure becomes the run's error and what was drawn stays. */
export function advance(it: Iterator<unknown>): { done: boolean; error: LogoError | null } {
  try {
    return { done: !!it.next().done, error: null };
  } catch (e) {
    if (e instanceof LogoFailure) return { done: true, error: e.toError() };
    throw e;
  }
}

export function run(source: string, mode: Mode): RunResult {
  const compiled = compile(source, mode);
  if (compiled.error) return { segments: [], error: compiled.error };
  const machine = new Machine(compiled.program);
  const it = machine.steps();
  for (;;) {
    const { done, error } = advance(it);
    if (error) return { segments: machine.segments, error };
    if (done) return { segments: machine.segments, error: null };
  }
}
EOF
