    if (to.some((c) => Math.abs(c) > MAX_COORDINATE))
      throw new LogoFailure(`Żółw wyszedłby poza obszar rysowania: współrzędne muszą mieścić się w ±${pl(MAX_COORDINATE)}.`, at.line, at.column);
    const from = this.pos;
    const moved = from[0] !== to[0] || from[1] !== to[1] || from[2] !== to[2];
