import { advance, compile, Machine, type LogoError, type Mode, type Segment, type Token, type TurtleState } from "../lang";

/** Animation frames and the clock; injected so a test can drive time by hand. */
export interface FrameScheduler {
  /** Call `cb` on the next animation frame; returns a cancel function. */
  request(cb: (now: number) => void): () => void;
  now(): number;
}

export const browserScheduler: FrameScheduler = {
  request(cb) {
    const id = requestAnimationFrame(cb);
    return () => cancelAnimationFrame(id);
  },
  now: () => performance.now(),
};

export type Status = "idle" | "running" | "paused" | "done" | "error" | "stopped";

export interface Position {
  line: number;
  column: number;
}

export interface ControllerState {
  status: Status;
  mode: Mode;
  source: string;
  segments: Segment[];
  turtle: TurtleState;
  /** The command being (or just) executed, for highlighting. */
  current: Position | null;
  error: LogoError | null;
  speed: number;
}

/** Commands per second for speed levels 1–10; level 10 draws everything at once. */
export const SPEEDS = [1, 2, 4, 8, 16, 32, 64, 160, 480, Infinity];
export const MAX_SPEED = SPEEDS.length;

export const HOME: TurtleState = {
  pos: [0, 0, 0],
  heading: [0, 1, 0],
  right: [1, 0, 0],
  up: [0, 0, 1],
  penDown: true,
  color: "#16866a",
  width: 3,
};

export interface Controller {
  readonly state: ControllerState;
  /** Set the program. Changing it while a run is active stops that run and keeps its drawing. */
  load(source: string, mode: Mode): void;
  /** Start from the beginning, or resume when paused. */
  run(): void;
  /** Execute one command, then pause. Starts a new run if none is active. */
  step(): void;
  pause(): void;
  resume(): void;
  /** Stop and clear the drawing. */
  reset(): void;
  /** Run whatever remains (or the whole program) to the end without animation. */
  finish(): void;
  setSpeed(level: number): void;
  subscribe(listener: (state: ControllerState) => void): () => void;
}

export function createController(options: { scheduler?: FrameScheduler } = {}): Controller {
  const scheduler = options.scheduler ?? browserScheduler;
  const listeners = new Set<(state: ControllerState) => void>();
  let state: ControllerState = {
    status: "idle",
    mode: "2d",
    source: "",
    segments: [],
    turtle: HOME,
    current: null,
    error: null,
    speed: 6,
  };
  let machine: Machine | null = null;
  let steps: Generator<Token, void, void> | null = null;
  /** The statement the machine will start next. */
  let pending: Token | null = null;
  let cancelFrame: (() => void) | null = null;
  let lastFrame = 0;
  let budget = 0;

  const emit = (patch: Partial<ControllerState>) => {
    state = { ...state, ...patch };
    for (const l of listeners) l(state);
  };

  const stopFrames = () => {
    cancelFrame?.();
    cancelFrame = null;
  };

  const active = () => state.status === "running" || state.status === "paused";

  /** Compile and prepare a fresh machine; false when the program does not parse. */
  function start(): boolean {
    stopFrames();
    const compiled = compile(state.source, state.mode);
    if (compiled.error) {
      machine = steps = pending = null;
      emit({ status: "error", error: compiled.error, segments: [], turtle: HOME, current: { ...compiled.error } });
      return false;
    }
    machine = new Machine(compiled.program);
    steps = machine.steps();
    const first = advance(steps);
    pending = null;
    if (!first.done) pending = (steps as unknown as { lastValue?: Token }).lastValue ?? null;
    return true;
  }

  /** Execute the pending statement; returns false when the run is over. */
  function stepOnce(): boolean {
    if (!machine || !steps) return false;
    const current = pending;
    let next: IteratorResult<Token, void>;
    try {
      next = steps.next();
    } catch (e) {
      const { error } = advance({
        next() {
          throw e;
        },
      });
      if (!error) throw e;
      finishWith("error", error, { line: error.line, column: error.column });
      return false;
    }
    if (next.done) {
      finishWith("done", null, null);
      return false;
    }
    pending = next.value;
    emit({ segments: machine.segments, turtle: machine.turtle, current: current && { line: current.line, column: current.column } });
    return true;
  }

  function finishWith(status: Status, error: LogoError | null, current: Position | null) {
    stopFrames();
    const m = machine!;
    machine = steps = pending = null;
    emit({ status, error, current, segments: m.segments, turtle: m.turtle });
  }

  function schedule() {
    cancelFrame = scheduler.request(onFrame);
  }

  function onFrame(now: number) {
    cancelFrame = null;
    if (state.status !== "running") return;
    const rate = SPEEDS[state.speed - 1];
    budget += rate === Infinity ? Infinity : ((now - lastFrame) * rate) / 1000;
    lastFrame = now;
    while (budget >= 1) {
      budget--;
      if (!stepOnce()) return;
    }
    schedule();
  }

  function beginRunning() {
    lastFrame = scheduler.now();
    budget = 1; // the first command starts right away
    emit({ status: "running", error: null });
    schedule();
  }

  return {
    get state() {
      return state;
    },
    load(source, mode) {
      if (mode !== state.mode) {
        stopFrames();
        machine = steps = pending = null;
        emit({ source, mode, status: "idle", segments: [], turtle: HOME, current: null, error: null });
        return;
      }
      if (source === state.source) return;
      if (active()) {
        stopFrames();
        machine = steps = pending = null;
        emit({ source, status: "stopped", current: null });
        return;
      }
      emit({ source });
    },
    run() {
      if (state.status === "paused") return this.resume();
      if (state.status === "running") return;
      emit({ error: null, segments: [], turtle: HOME, current: null });
      if (start()) beginRunning();
    },
    step() {
      if (state.status === "running") {
        stopFrames();
        emit({ status: "paused" });
      }
      if (state.status !== "paused") {
        emit({ error: null, segments: [], turtle: HOME, current: null });
        if (!start()) return;
        emit({ status: "paused" });
      }
      stepOnce();
    },
    pause() {
      if (state.status !== "running") return;
      stopFrames();
      emit({ status: "paused" });
    },
    resume() {
      if (state.status !== "paused") return;
      beginRunning();
    },
    reset() {
      stopFrames();
      machine = steps = pending = null;
      emit({ status: "idle", segments: [], turtle: HOME, current: null, error: null });
    },
    finish() {
      if (!active()) {
        emit({ error: null, segments: [], turtle: HOME, current: null });
        if (!start()) return;
      }
      stopFrames();
      while (stepOnce());
    },
    setSpeed(level) {
      emit({ speed: Math.min(MAX_SPEED, Math.max(1, Math.round(level))) });
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}
