cat >> tests/controller.test.ts <<'EOF'

describe("stepping", () => {
  const setup = (src: string, mode: "2d" | "3d" = "2d") => {
    const clock = fakeClock();
    const c = createController({ scheduler: clock.scheduler });
    c.load(src, mode);
    return { c, clock };
  };
  const snapshot = (c: ReturnType<typeof createController>) => ({
    status: c.state.status,
    line: c.state.current?.line ?? null,
    strokes: c.state.segments.length,
  });

  test("each step executes one command, pauses, and marks its line", () => {
    const { c } = setup("np 10\npw 90\nnp 20");
    const seen = [];
    for (let i = 0; i < 4; i++) {
      c.step();
      seen.push(snapshot(c));
    }
    expect(seen).toEqual([
      { status: "paused", line: 1, strokes: 1 },
      { status: "paused", line: 2, strokes: 1 },
      { status: "paused", line: 3, strokes: 2 },
      { status: "done", line: null, strokes: 2 },
    ]);
    expect(c.state.turtle.pos).toEqual([20, 10, 0]);
  });

  test("a repeat is one step, then each command of each iteration", () => {
    const { c } = setup("powtorz 2 [\n  np 5\n]\npw 1");
    const lines = [];
    for (let i = 0; i < 4; i++) {
      c.step();
      lines.push(c.state.current?.line);
    }
    expect(lines).toEqual([1, 2, 2, 4]);
    expect(c.state.segments.length).toBe(2);
  });

  test("stepping into a run-time error stops with the error and keeps the drawing", () => {
    const { c } = setup("np 10\nnp 1 / 0\nnp 5");
    c.step();
    c.step();
    expect(c.state.status).toBe("error");
    expect(c.state.error).toMatchObject({ line: 2, column: 4 });
    expect(c.state.segments.length).toBe(1);
  });

  test("stepping a program with a parse error draws nothing and reports it", () => {
    const { c } = setup("np 10\nnp (");
    c.step();
    expect(c.state.status).toBe("error");
    expect(c.state.segments).toEqual([]);
    expect(c.state.error).toMatchObject({ line: 2 });
  });
});
EOF
