describe("pause, resume, reset", () => {
  const prog = "powtorz 40 [np 5 pw 9]";

  test("pause freezes the drawing; resume continues to the same end result", () => {
    const clock = fakeClock();
    const c = createController({ scheduler: clock.scheduler });
    c.load(prog, "2d");
    c.setSpeed(5); // 16 commands per second
    c.run();
    clock.frames(60); // about a second
    c.pause();
    const frozen = c.state.segments.length;
    expect(c.state.status).toBe("paused");
    expect(frozen).toBeGreaterThan(0);
    expect(frozen).toBeLessThan(40);
    clock.frames(200);
    expect(c.state.segments.length).toBe(frozen);
    c.resume();
    clock.frames(5000);
    expect(c.state.status).toBe("done");
    expect(c.state.segments).toEqual(run(prog, "2d").segments);
  });

  test("run while paused resumes instead of restarting", () => {
    const clock = fakeClock();
    const c = createController({ scheduler: clock.scheduler });
    c.load(prog, "2d");
    c.step();
    c.step();
    c.step();
    c.run();
    expect(c.state.status).toBe("running");
    expect(c.state.segments.length).toBe(1);
  });

  test("a faster speed draws more in the same time; the top speed draws everything in one frame", () => {
    const drawnAfterASecond = (speed: number) => {
      const clock = fakeClock();
      const c = createController({ scheduler: clock.scheduler });
      c.load(prog, "2d");
      c.setSpeed(speed);
      c.run();
      clock.frames(62);
      return c.state.segments.length;
    };
    expect(drawnAfterASecond(3)).toBeLessThan(drawnAfterASecond(6));
    const clock = fakeClock();
    const c = createController({ scheduler: clock.scheduler });
    c.load(prog, "2d");
    c.setSpeed(10);
    c.run();
    clock.frame();
    expect(c.state.status).toBe("done");
  });

  test("reset stops the run, clears the drawing and sends the turtle home", () => {
    const clock = fakeClock();
    const c = createController({ scheduler: clock.scheduler });
    c.load(prog, "2d");
    c.run();
    clock.frames(100);
    c.reset();
    expect(c.state).toMatchObject({ status: "idle", segments: [], current: null, error: null });
    expect(c.state.turtle.pos).toEqual([0, 0, 0]);
    clock.frames(100);
    expect(c.state.segments).toEqual([]);
  });

  test("editing the program during a run stops it and keeps what was drawn", () => {
    const clock = fakeClock();
    const c = createController({ scheduler: clock.scheduler });
    c.load(prog, "2d");
    c.run();
    clock.frames(100);
    const drawn = c.state.segments.length;
    c.load(prog + "\nnp 1", "2d");
    expect(c.state.status).toBe("stopped");
    clock.frames(100);
    expect(c.state.segments.length).toBe(drawn);
    c.run();
    clock.frames(100_000);
    expect(c.state.segments).toEqual(run(prog + "\nnp 1", "2d").segments);
  });

  test("finish completes the remaining commands immediately", () => {
    const clock = fakeClock();
    const c = createController({ scheduler: clock.scheduler });
    c.load(prog, "2d");
    c.step();
    c.finish();
    expect(c.state.status).toBe("done");
    expect(c.state.segments.length).toBe(40);
  });
});
EOF
