/** Local persistence; every read and write tolerates a missing or full storage. */
export interface Store {
  get(key: string): string | null;
  set(key: string, value: string): void;
  remove(key: string): void;
  getJSON<T>(key: string, fallback: T): T;
  setJSON(key: string, value: unknown): void;
}

const PREFIX = "logomocja:";

export function createStore(storage: Storage | null | undefined): Store {
  const store: Store = {
    get(key) {
      try {
        return storage?.getItem(PREFIX + key) ?? null;
      } catch {
        return null;
      }
    },
    set(key, value) {
      try {
        storage?.setItem(PREFIX + key, value);
      } catch {
        // Storage may be full or disabled; the app keeps working without it.
      }
    },
    remove(key) {
      try {
        storage?.removeItem(PREFIX + key);
      } catch {
        // ignore
      }
    },
    getJSON(key, fallback) {
      const raw = store.get(key);
      if (raw === null) return fallback;
      try {
        return JSON.parse(raw);
      } catch {
        return fallback;
      }
    },
    setJSON(key, value) {
      store.set(key, JSON.stringify(value));
    },
  };
  return store;
}
