import { KEYWORDS, VALUE_WORDS } from "../lang";

export type TokenClass = "comment" | "string" | "number" | "keyword" | "value" | "proc" | "name" | "bracket" | "paren" | "op" | "text";

export interface Span {
  cls: TokenClass;
  text: string;
  /** 1-based column of the span's first character. */
  column: number;
}

const WORD = /[\p{L}\p{N}_]/u;

/** Names defined with `oto` anywhere in the source, so calls can be coloured as procedures. */
export function definedProcedures(source: string): Set<string> {
  const names = new Set<string>();
  for (const m of source.matchAll(/^[ \t]*(?:oto|to)[ \t]+([\p{L}\p{N}_]+)/gimu)) names.add(m[1].toLowerCase());
  return names;
}

/** Split one line into classified spans. Never throws: it colours what it can and leaves the rest as text. */
export function highlightLine(line: string, procedures: Set<string>): Span[] {
  const spans: Span[] = [];
  let i = 0;
  const push = (cls: TokenClass, end: number) => {
    spans.push({ cls, text: line.slice(i, end), column: i + 1 });
    i = end;
  };
  while (i < line.length) {
    const c = line[i];
    if (c === ";") {
      push("comment", line.length);
    } else if (c === '"') {
      const close = line.indexOf('"', i + 1);
      push("string", close === -1 ? line.length : close + 1);
    } else if (/[0-9]/.test(c) || (c === "." && /[0-9]/.test(line[i + 1] ?? ""))) {
      let j = i;
      while (j < line.length && /[0-9.]/.test(line[j])) j++;
      push("number", j);
    } else if (c === ":" && WORD.test(line[i + 1] ?? "")) {
      let j = i + 1;
      while (j < line.length && WORD.test(line[j])) j++;
      push("name", j);
    } else if (WORD.test(c)) {
      let j = i;
      while (j < line.length && WORD.test(line[j])) j++;
      if (line[j] === ":" && line.slice(i, j).toLowerCase() === "ma") j++;
      const word = line.slice(i, j).toLowerCase();
      const cls: TokenClass = VALUE_WORDS.has(word)
        ? "value"
        : KEYWORDS.has(word) || word === "ma:"
          ? "keyword"
          : procedures.has(word)
            ? "proc"
            : "name";
      push(cls, j);
    } else if (c === "[" || c === "]") {
      push("bracket", i + 1);
    } else if (c === "(" || c === ")") {
      push("paren", i + 1);
    } else if ("+-*/<>=,".includes(c)) {
      push("op", i + 1);
    } else {
      let j = i + 1;
      while (j < line.length && /\s/.test(line[j])) j++;
      push("text", j);
    }
  }
  return spans;
}
