import type { Segment, TurtleState, Vec3 } from "../lang";
import { h } from "./dom";

/** Maps a turtle-space point to the plane of the canvas (+y up). */
export type Projection = (p: Vec3) => [number, number];

export const flatProjection: Projection = (p) => [p[0], p[1]];

/** A fixed isometric-style view of space, used when WebGL is unavailable and for thumbnails. */
export const isoProjection: Projection = (p) => {
  const c = Math.cos(Math.PI / 6);
  return [(p[0] - p[1]) * c, (p[0] + p[1]) * 0.5 + p[2]];
};

export interface Scene {
  segments: Segment[];
  turtle: TurtleState | null;
}

export interface Palette {
  background: string;
  grid: string;
  axis: string;
  origin: string;
  turtle: string;
}

export function readPalette(el: Element = document.documentElement): Palette {
  const css = getComputedStyle(el);
  const v = (name: string, fallback: string) => css.getPropertyValue(name).trim() || fallback;
  return {
    background: v("--canvas-bg", "#fbfaf6"),
    grid: v("--canvas-grid", "rgba(40,40,30,0.07)"),
    axis: v("--canvas-axis", "rgba(40,40,30,0.25)"),
    origin: v("--canvas-origin", "#c1763d"),
    turtle: v("--canvas-turtle", "#1d2b24"),
  };
}

interface Camera {
  /** World point at the centre of the view. */
  x: number;
  y: number;
  /** CSS pixels per unit. */
  scale: number;
}

export function bounds(points: [number, number][]) {
  let minX = Infinity,
    minY = Infinity,
    maxX = -Infinity,
    maxY = -Infinity;
  for (const [x, y] of points) {
    if (x < minX) minX = x;
    if (y < minY) minY = y;
    if (x > maxX) maxX = x;
    if (y > maxY) maxY = y;
  }
  return points.length ? { minX, minY, maxX, maxY } : null;
}

export function fitCamera(points: [number, number][], width: number, height: number, margin = 32, maxScale = 6): Camera {
  const b = bounds(points);
  if (!b || width <= 0 || height <= 0) return { x: 0, y: 0, scale: 1 };
  const w = Math.max(b.maxX - b.minX, 1e-9);
  const hgt = Math.max(b.maxY - b.minY, 1e-9);
  const scale = Math.min((width - 2 * margin) / w, (height - 2 * margin) / hgt, maxScale);
  return { x: (b.minX + b.maxX) / 2, y: (b.minY + b.maxY) / 2, scale: Math.max(scale, 0.0005) };
}

/** Draw a scene on a 2D context; shared by the live view, PNG export and thumbnails. */
export function paint(
  ctx: CanvasRenderingContext2D,
  scene: Scene,
  cam: Camera,
  size: { width: number; height: number; dpr: number },
  palette: Palette,
  options: { projection?: Projection; grid?: boolean; origin?: boolean; lineScale?: number } = {},
) {
  const project = options.projection ?? flatProjection;
  const { width, height, dpr } = size;
  const toScreen = (p: Vec3): [number, number] => {
    const [x, y] = project(p);
    return [(width / 2 + (x - cam.x) * cam.scale) * dpr, (height / 2 - (y - cam.y) * cam.scale) * dpr];
  };
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, width * dpr, height * dpr);

  if (options.grid !== false) {
    // Grid spacing: a round number of units that is 24–120 px on screen.
    let step = 10;
    while (step * cam.scale < 24) step *= step.toString().startsWith("1") ? 5 : 2;
    while (step * cam.scale > 120 && step > 1e-3) step /= step.toString().startsWith("5") ? 5 : 2;
    const left = cam.x - width / 2 / cam.scale;
    const right = cam.x + width / 2 / cam.scale;
    const bottom = cam.y - height / 2 / cam.scale;
    const top = cam.y + height / 2 / cam.scale;
    ctx.lineWidth = dpr;
    ctx.strokeStyle = palette.grid;
    ctx.beginPath();
    if (options.projection === undefined || options.projection === flatProjection) {
      for (let x = Math.ceil(left / step) * step; x <= right; x += step) {
        const sx = (width / 2 + (x - cam.x) * cam.scale) * dpr;
        ctx.moveTo(sx, 0);
        ctx.lineTo(sx, height * dpr);
      }
      for (let y = Math.ceil(bottom / step) * step; y <= top; y += step) {
        const sy = (height / 2 - (y - cam.y) * cam.scale) * dpr;
        ctx.moveTo(0, sy);
        ctx.lineTo(width * dpr, sy);
      }
    }
    ctx.stroke();
  }

  if (options.origin !== false) {
    const big = 1e6;
    ctx.strokeStyle = palette.axis;
    ctx.lineWidth = dpr;
    ctx.beginPath();
    for (const axis of [
      [
        [-big, 0, 0],
        [big, 0, 0],
      ],
      [
        [0, -big, 0],
        [0, big, 0],
      ],
    ] as [Vec3, Vec3][]) {
      const [a, b] = [toScreen(axis[0]), toScreen(axis[1])];
      ctx.moveTo(a[0], a[1]);
      ctx.lineTo(b[0], b[1]);
    }
    ctx.stroke();
    const [ox, oy] = toScreen([0, 0, 0]);
    ctx.fillStyle = palette.origin;
    ctx.beginPath();
    ctx.arc(ox, oy, 3.5 * dpr, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  const lineScale = options.lineScale ?? 1;
  // Batch consecutive strokes of the same style into one path.
  let style = "";
  let open = false;
  for (const s of scene.segments) {
    const key = s.color + s.width;
    if (key !== style) {
      if (open) ctx.stroke();
      ctx.strokeStyle = s.color;
      ctx.lineWidth = Math.max(1, s.width * lineScale) * dpr;
      ctx.beginPath();
      style = key;
      open = true;
    }
    const [ax, ay] = toScreen(s.from);
    const [bx, by] = toScreen(s.to);
    ctx.moveTo(ax, ay);
    ctx.lineTo(bx, by);
  }
  if (open) ctx.stroke();

  if (scene.turtle) drawTurtle(ctx, scene.turtle, toScreen, dpr, palette);
  ctx.restore();
}

function drawTurtle(ctx: CanvasRenderingContext2D, t: TurtleState, toScreen: (p: Vec3) => [number, number], dpr: number, palette: Palette) {
  const [px, py] = toScreen(t.pos);
  const ahead: Vec3 = [t.pos[0] + t.heading[0], t.pos[1] + t.heading[1], t.pos[2] + t.heading[2]];
  const [hx, hy] = toScreen(ahead);
  let dx = hx - px;
  let dy = hy - py;
  const len = Math.hypot(dx, dy);
  if (len < 1e-9) {
    // Heading straight at the viewer: show a dot.
    ctx.fillStyle = palette.turtle;
    ctx.beginPath();
    ctx.arc(px, py, 5 * dpr, 0, Math.PI * 2);
    ctx.fill();
    return;
  }
  dx /= len;
  dy /= len;
  const size = 13 * dpr;
  const nx = -dy;
  const ny = dx;
  ctx.beginPath();
  ctx.moveTo(px + dx * size, py + dy * size);
  ctx.lineTo(px - dx * size * 0.6 + nx * size * 0.62, py - dy * size * 0.6 + ny * size * 0.62);
  ctx.lineTo(px - dx * size * 0.3, py - dy * size * 0.3);
  ctx.lineTo(px - dx * size * 0.6 - nx * size * 0.62, py - dy * size * 0.6 - ny * size * 0.62);
  ctx.closePath();
  ctx.lineWidth = 2 * dpr;
  ctx.strokeStyle = palette.turtle;
  ctx.fillStyle = t.penDown ? t.color : palette.background;
  ctx.globalAlpha = 0.92;
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.stroke();
}

export interface View2D {
  element: HTMLElement;
  canvas: HTMLCanvasElement;
  show(scene: Scene): void;
  fit(): void;
  zoomBy(factor: number): void;
  pan(dx: number, dy: number): void;
  /** Whether the user moved the camera since the last fit. */
  readonly userMoved: boolean;
  refreshTheme(): void;
  toBlob(): Promise<Blob | null>;
  destroy(): void;
}

export function createView2D(options: { projection?: Projection; label: string; request?: (cb: () => void) => void }): View2D {
  const canvas = h("canvas", { class: "view-canvas", tabindex: "0", role: "img", "aria-label": options.label });
  const element = h("div", { class: "view2d" }, canvas);
  const ctx = canvas.getContext("2d");
  const projection = options.projection ?? flatProjection;
  let scene: Scene = { segments: [], turtle: null };
  let cam: Camera = { x: 0, y: 0, scale: 1 };
  let userMoved = false;
  let palette = readPalette();
  let queued = false;
  const request = options.request ?? ((cb: () => void) => requestAnimationFrame(() => cb()));

  const size = () => ({ width: canvas.clientWidth || 600, height: canvas.clientHeight || 400, dpr: window.devicePixelRatio || 1 });

  function draw() {
    queued = false;
    if (!ctx) return;
    const s = size();
    const w = Math.round(s.width * s.dpr);
    const hh = Math.round(s.height * s.dpr);
    if (canvas.width !== w || canvas.height !== hh) {
      canvas.width = w;
      canvas.height = hh;
    }
    paint(ctx, scene, cam, s, palette, { projection });
  }

  function schedule() {
    if (queued) return;
    queued = true;
    request(draw);
  }

  const points = (): [number, number][] => {
    const pts: [number, number][] = [];
    for (const s of scene.segments) pts.push(projection(s.from), projection(s.to));
    if (scene.turtle) pts.push(projection(scene.turtle.pos));
    pts.push([0, 0]);
    return pts;
  };

  // Pointer pan and pinch zoom.
  const pointers = new Map<number, { x: number; y: number }>();
  let pinch = 0;
  canvas.addEventListener("pointerdown", (e) => {
    canvas.setPointerCapture?.(e.pointerId);
    pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pointers.size === 2) {
      const [a, b] = [...pointers.values()];
      pinch = Math.hypot(a.x - b.x, a.y - b.y);
    }
  });
  canvas.addEventListener("pointermove", (e) => {
    const prev = pointers.get(e.pointerId);
    if (!prev) return;
    pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pointers.size === 1) {
      view.pan(e.clientX - prev.x, e.clientY - prev.y);
    } else if (pointers.size === 2) {
      const [a, b] = [...pointers.values()];
      const d = Math.hypot(a.x - b.x, a.y - b.y);
      if (pinch > 0) view.zoomBy(d / pinch);
      pinch = d;
    }
  });
  const release = (e: PointerEvent) => {
    pointers.delete(e.pointerId);
    pinch = 0;
  };
  canvas.addEventListener("pointerup", release);
  canvas.addEventListener("pointercancel", release);
  canvas.addEventListener(
    "wheel",
    (e) => {
      e.preventDefault();
      const rect = canvas.getBoundingClientRect();
      const factor = Math.exp(-e.deltaY * (e.deltaMode === 1 ? 0.05 : 0.0015));
      zoomAt(factor, e.clientX - rect.left, e.clientY - rect.top);
    },
    { passive: false },
  );
  canvas.addEventListener("dblclick", () => view.fit());
  canvas.addEventListener("keydown", (e) => {
    const step = 40;
    const actions: Record<string, () => void> = {
      ArrowLeft: () => view.pan(step, 0),
      ArrowRight: () => view.pan(-step, 0),
      ArrowUp: () => view.pan(0, step),
      ArrowDown: () => view.pan(0, -step),
      "+": () => view.zoomBy(1.25),
      "=": () => view.zoomBy(1.25),
      "-": () => view.zoomBy(0.8),
      "0": () => view.fit(),
    };
    const act = actions[e.key];
    if (act && !e.ctrlKey && !e.metaKey && !e.altKey) {
