    const wy = cam.y - (sy - s.height / 2) / cam.scale;
    const scale = Math.min(500, Math.max(0.0005, cam.scale * factor));
    cam = { scale, x: wx - (sx - s.width / 2) / scale, y: wy + (sy - s.height / 2) / scale };
    userMoved = true;
    schedule();
  }

  const resize = typeof ResizeObserver !== "undefined" ? new ResizeObserver(() => schedule()) : null;
  resize?.observe(canvas);

  const view: View2D = {
    element,
    canvas,
    show(next) {
      scene = next;
