import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { LineMaterial } from "three/examples/jsm/lines/LineMaterial.js";
import { LineSegments2 } from "three/examples/jsm/lines/LineSegments2.js";
import { LineSegmentsGeometry } from "three/examples/jsm/lines/LineSegmentsGeometry.js";
import type { Segment, TurtleState } from "../lang";
import { readPalette, type Scene } from "./view2d";

export interface View3D {
  element: HTMLElement;
  show(scene: Scene): void;
  fit(): void;
  resetCamera(): void;
  zoomBy(factor: number): void;
  readonly userMoved: boolean;
  refreshTheme(): void;
  /** Render now (used before a screenshot or export). */
  renderNow(): void;
  toBlob(): Promise<Blob | null>;
  destroy(): void;
}

const DEFAULT_DIRECTION = new THREE.Vector3(0.55, -0.75, 0.6).normalize();

function textSprite(text: string, color: string) {
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const g = c.getContext("2d")!;
  g.font = "bold 40px system-ui, sans-serif";
  g.textAlign = "center";
  g.textBaseline = "middle";
  g.fillStyle = color;
  g.fillText(text, 32, 34);
  const tex = new THREE.CanvasTexture(c);
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, depthTest: false, transparent: true }));
  sprite.scale.set(18, 18, 1);
  return sprite;
}

/** Create the WebGL view. Throws when WebGL cannot be initialised. */
export function createView3D(label: string): View3D {
  const element = document.createElement("div");
  element.className = "view3d";
  const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  const canvas = renderer.domElement;
  canvas.classList.add("view-canvas");
  canvas.tabIndex = 0;
  canvas.setAttribute("role", "img");
  canvas.setAttribute("aria-label", label);
  element.appendChild(canvas);

  const scene3 = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(45, 1, 0.5, 20000);
  camera.up.set(0, 0, 1);
  const controls = new OrbitControls(camera, canvas);
  controls.enableDamping = true;
  controls.dampingFactor = 0.12;
  controls.screenSpacePanning = true;

  let palette = readPalette();
  const helpers = new THREE.Group();
  scene3.add(helpers);

  function buildHelpers() {
    helpers.clear();
    const grid = new THREE.GridHelper(1000, 20, new THREE.Color(palette.axis), new THREE.Color(palette.grid));
    grid.rotation.x = Math.PI / 2; // three's grid lies in XZ; ours is the XY ground
    const gm = grid.material as THREE.Material;
    gm.transparent = true;
    gm.opacity = 0.55;
    helpers.add(grid);
    const axisLen = 160;
    const axes: [THREE.Vector3, string, string][] = [
      [new THREE.Vector3(axisLen, 0, 0), "#d0473a", "X"],
      [new THREE.Vector3(0, axisLen, 0), "#2f9a4c", "Y"],
      [new THREE.Vector3(0, 0, axisLen), "#3b6fd0", "Z"],
    ];
    for (const [end, color, name] of axes) {
      const geo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), end]);
      helpers.add(new THREE.Line(geo, new THREE.LineBasicMaterial({ color })));
      const sprite = textSprite(name, color);
      sprite.position.copy(end.clone().multiplyScalar(1.1));
      helpers.add(sprite);
    }
    const origin = new THREE.Mesh(new THREE.SphereGeometry(3, 16, 12), new THREE.MeshBasicMaterial({ color: palette.origin }));
    helpers.add(origin);
    scene3.background = new THREE.Color(palette.background);
  }
  buildHelpers();

  // Turtle: a cone along the heading and a fin along the up vector, so roll is visible.
  const turtle = new THREE.Group();
  const coneMat = new THREE.MeshStandardMaterial({ color: "#16866a", roughness: 0.5, metalness: 0.05 });
  const cone = new THREE.Mesh(new THREE.ConeGeometry(5, 16, 20), coneMat);
  turtle.add(cone);
  const finGeo = new THREE.BufferGeometry();
  finGeo.setAttribute("position", new THREE.Float32BufferAttribute([0, -6, 0, 0, 5, 0, 0, -4, 10], 3));
  finGeo.computeVertexNormals();
  const fin = new THREE.Mesh(finGeo, new THREE.MeshStandardMaterial({ color: palette.turtle, side: THREE.DoubleSide }));
  turtle.add(fin);
  scene3.add(turtle);
  scene3.add(new THREE.AmbientLight(0xffffff, 1.6));
  const sun = new THREE.DirectionalLight(0xffffff, 1.6);
  sun.position.set(200, -300, 500);
  scene3.add(sun);

  let lines: LineSegments2[] = [];
  let materials: LineMaterial[] = [];
  let current: Scene = { segments: [], turtle: null };
  let shownSegments: Segment[] | null = null;
  let shownLength = -1;
  let userMoved = false;
  let disposed = false;
  let frame = 0;

  controls.addEventListener("start", () => {
    userMoved = true;
  });

  function rebuildLines(segments: Segment[]) {
    for (const l of lines) {
      scene3.remove(l);
      l.geometry.dispose();
    }
    for (const m of materials) m.dispose();
    lines = [];
    materials = [];
    const byWidth = new Map<number, Segment[]>();
    for (const s of segments) {
      const list = byWidth.get(s.width) ?? [];
      list.push(s);
      byWidth.set(s.width, list);
    }
    const color = new THREE.Color();
    for (const [width, list] of byWidth) {
      const positions = new Float32Array(list.length * 6);
      const colors = new Float32Array(list.length * 6);
      list.forEach((s, i) => {
        positions.set([...s.from, ...s.to], i * 6);
        color.set(s.color);
        colors.set([color.r, color.g, color.b, color.r, color.g, color.b], i * 6);
      });
      const geo = new LineSegmentsGeometry();
      geo.setPositions(positions);
      geo.setColors(colors);
      const mat = new LineMaterial({ linewidth: width, vertexColors: true, worldUnits: false });
      mat.resolution.set(canvas.clientWidth || 600, canvas.clientHeight || 400);
      const line = new LineSegments2(geo, mat);
      scene3.add(line);
      lines.push(line);
      materials.push(mat);
    }
  }

  function placeTurtle(t: TurtleState | null) {
    turtle.visible = !!t;
    if (!t) return;
    const basis = new THREE.Matrix4().makeBasis(
      new THREE.Vector3(...t.right),
      new THREE.Vector3(...t.heading),
      new THREE.Vector3(...t.up),
    );
    turtle.quaternion.setFromRotationMatrix(basis);
    turtle.position.set(...t.pos);
    coneMat.color.set(t.penDown ? t.color : palette.background);
  }

  function resize() {
    const w = element.clientWidth || 600;
    const hgt = element.clientHeight || 400;
    if (canvas.width !== Math.round(w * renderer.getPixelRatio()) || canvas.height !== Math.round(hgt * renderer.getPixelRatio())) {
