    const v = new THREE.Vector3().setFromSpherical(sph);
    camera.position.copy(controls.target).add(new THREE.Vector3(v.x, -v.z, v.y));
    userMoved = true;
    controls.update();
  });

  const view: View3D = {
    element,
    show(next) {
      current = next;
    },
    fit() {
      const dir = camera.position.clone().sub(controls.target);
      frameSphere(dir.lengthSq() > 0 ? dir.normalize() : DEFAULT_DIRECTION.clone());
    },
    resetCamera() {
      frameSphere(DEFAULT_DIRECTION.clone());
    },
    zoomBy(factor) {
      const offset = camera.position.clone().sub(controls.target).multiplyScalar(1 / factor);
      camera.position.copy(controls.target).add(offset);
      userMoved = true;
      controls.update();
    },
    get userMoved() {
      return userMoved;
    },
    refreshTheme() {
      palette = readPalette();
      buildHelpers();
      (fin.material as THREE.MeshStandardMaterial).color.set(palette.turtle);
    },
    renderNow,
    toBlob() {
      renderNow();
      return new Promise((resolve) => canvas.toBlob((b) => resolve(b), "image/png"));
    },
    destroy() {
      disposed = true;
      cancelAnimationFrame(frame);
      controls.dispose();
      renderer.dispose();
    },
  };
  camera.position.copy(DEFAULT_DIRECTION).multiplyScalar(500);
  controls.target.set(0, 0, 0);
  loop();
  return view;
}
