import { version } from "../../package.json";
import { run, type Mode, type RunResult } from "../lang";
import { createController, MAX_SPEED, type Controller, type ControllerState, type FrameScheduler } from "../runner/controller";
import { h, icon, ICONS } from "./dom";
import { createEditor } from "./editor";
import { createStore } from "./storage";
import { createViewHost } from "./viewhost";

export interface AppEnv {
  scheduler?: FrameScheduler;
  storage?: Storage | null;
}

export interface App {
  open(source: string, mode: Mode): Promise<RunResult>;
  readonly controller: Controller;
  destroy(): void;
}

export interface LogomocjaHook {
  version: string;
  run(source: string, mode: Mode): RunResult;
  open(source: string, mode: Mode): Promise<RunResult>;
}

const STATUS_TEXT: Record<ControllerState["status"], string> = {
  idle: "Gotowe do uruchomienia",
  running: "Rysuję…",
  paused: "Wstrzymano",
  done: "Zakończono",
  error: "Błąd",
  stopped: "Zatrzymano: program został zmieniony",
};

/** Wait until the browser has painted the current frame (with a fallback for hidden tabs). */
const painted = () =>
  new Promise<void>((resolve) => {
    let done = false;
    const finish = () => {
      if (!done) {
        done = true;
        resolve();
      }
    };
    requestAnimationFrame(() => requestAnimationFrame(finish));
    setTimeout(finish, 120);
  });

export function mountApp(root: HTMLElement, env: AppEnv = {}): App {
  const store = createStore(env.storage === undefined ? globalThis.localStorage : env.storage);
  const controller = createController({ scheduler: env.scheduler });
  let mode: Mode = store.get("mode") === "3d" ? "3d" : "2d";

  // ---- Studio -------------------------------------------------------------
  const editor = createEditor({ id: "program", describedBy: "editor-help" });
  const statusText = h("span", { class: "status-text" });
  const statusDetail = h("span", { class: "status-detail" });
  const errorBox = h("div", { class: "error-box", role: "alert", hidden: true });
  const viewHost = createViewHost({ store, request: (cb) => (env.scheduler ?? null) ? cb() : requestAnimationFrame(() => cb()) });

  const toolButton = (label: string, iconPaths: string[], shortcut: string, onclick: () => void, extra: Record<string, string> = {}) =>
    h(
      "button",
      { type: "button", class: "tool", "aria-label": label, title: `${label} (${shortcut})`, "aria-keyshortcuts": extra.keys, onclick },
      icon(iconPaths, true),
      h("span", { class: "tool-label" }, label),
    );

  const runBtn = toolButton("Uruchom", ICONS.play, "Ctrl+Enter", () => controller.run(), { keys: "Control+Enter" });
  runBtn.classList.add("primary");
  const stepBtn = toolButton("Krok", ICONS.step, "Ctrl+Shift+Enter", () => controller.step(), { keys: "Control+Shift+Enter" });
  const pauseBtn = toolButton("Pauza", ICONS.pause, "Ctrl+.", () => togglePause(), { keys: "Control+." });
  const resetBtn = toolButton("Reset", ICONS.reset, "Esc", () => controller.reset(), { keys: "Escape" });
  const speed = h("input", {
    type: "range",
    id: "speed",
    min: "1",
    max: String(MAX_SPEED),
    step: "1",
    value: String(controller.state.speed),
    oninput: () => {
      controller.setSpeed(Number(speed.value));
      store.set("speed", speed.value);
    },
  });
  const savedSpeed = Number(store.get("speed"));
  if (savedSpeed >= 1 && savedSpeed <= MAX_SPEED) {
    controller.setSpeed(savedSpeed);
    speed.value = String(savedSpeed);
  }

  function togglePause() {
    if (controller.state.status === "running") controller.pause();
    else if (controller.state.status === "paused") controller.resume();
  }

  const modeButtons = (["2d", "3d"] as Mode[]).map((m) =>
    h(
      "button",
      { type: "button", class: "mode-btn", "aria-pressed": String(m === mode), "data-mode": m, onclick: () => switchMode(m) },
      m.toUpperCase(),
    ),
  );

  const studio = h(
    "section",
    { class: "studio", "aria-label": "Studio" },
    h(
      "div",
      { class: "workspace" },
      h(
        "section",
        { class: "pane editor-pane", "aria-label": "Edytor programu" },
        h(
          "div",
          { class: "toolbar", role: "toolbar", "aria-label": "Wykonanie programu" },
          runBtn,
          stepBtn,
          pauseBtn,
          resetBtn,
          h("label", { class: "speed", for: "speed" }, h("span", {}, "Szybkość"), speed),
        ),
        editor.element,
        errorBox,
        h("p", { id: "editor-help", class: "sr-only" }, "Edytor programu w języku Logo. Ctrl+Enter uruchamia program."),
      ),
      h(
        "section",
        { class: "pane view-pane", "aria-label": "Rysunek" },
        viewHost.element,
        h("div", { class: "statusbar", role: "status", "aria-live": "polite" }, statusText, statusDetail),
      ),
    ),
  );

  const header = h(
    "header",
    { class: "topbar" },
    h("a", { class: "brand", href: "#/" }, h("span", { class: "brand-mark", "aria-hidden": "true" }, "▲"), "Logomocja"),
    h("div", { class: "mode-switch", role: "group", "aria-label": "Tryb rysowania" }, modeButtons),
  );

  const shell = h("div", { class: "app" }, header, h("main", { id: "main" }, studio));
  root.replaceChildren(shell);

  // ---- Behaviour ----------------------------------------------------------
  function draftKey(m: Mode) {
    return `draft:${m}`;
  }

  function setSource(source: string) {
    editor.value = source;
    store.set(draftKey(mode), source);
    controller.load(source, mode);
  }

  function switchMode(next: Mode) {
    if (next === mode) return;
    store.set(draftKey(mode), editor.value);
    mode = next;
    store.set("mode", mode);
    for (const b of modeButtons) b.setAttribute("aria-pressed", String(b.dataset.mode === mode));
    editor.value = store.get(draftKey(mode)) ?? "";
    controller.load(editor.value, mode);
    viewHost.setMode(mode);
  }

  editor.onInput((value) => {
    store.set(draftKey(mode), value);
    controller.load(value, mode);
  });

  let lastStatus = "";
  const unsubscribe = controller.subscribe((s) => render(s));

  function render(s: ControllerState) {
    editor.setMarks(s.status === "running" || s.status === "paused" ? s.current : null, s.error);
    viewHost.show({ segments: s.segments, turtle: s.turtle });
    pauseBtn.querySelector(".tool-label")!.textContent = s.status === "paused" ? "Wznów" : "Pauza";
    pauseBtn.setAttribute("aria-label", s.status === "paused" ? "Wznów" : "Pauza");
    pauseBtn.replaceChild(icon(s.status === "paused" ? ICONS.play : ICONS.pause, true), pauseBtn.querySelector("svg")!);
    pauseBtn.disabled = !(s.status === "running" || s.status === "paused");
    const text = STATUS_TEXT[s.status];
    if (text !== lastStatus) {
      statusText.textContent = text;
      lastStatus = text;
    }
    statusDetail.textContent = describeTurtle(s);
    if (s.error) {
      errorBox.hidden = false;
      errorBox.replaceChildren(
        h("strong", {}, `Wiersz ${s.error.line}, kolumna ${s.error.column}: `),
        s.error.message,
        " ",
        h("button", { type: "button", class: "link", onclick: () => editor.focusAt(s.error!.line, s.error!.column) }, "Pokaż w programie"),
      );
    } else {
      errorBox.hidden = true;
      errorBox.replaceChildren();
    }
    if ((s.status === "done" || s.status === "error") && !viewHost.userMoved) viewHost.fit();
  }

  function describeTurtle(s: ControllerState) {
    const f = (n: number) => (Math.round(n * 10) / 10).toLocaleString("pl-PL");
    const p = s.turtle.pos;
    const where = mode === "2d" ? `x ${f(p[0])}, y ${f(p[1])}` : `x ${f(p[0])}, y ${f(p[1])}, z ${f(p[2])}`;
    const n = s.segments.length;
    return `${n} ${n === 1 ? "odcinek" : n % 10 >= 2 && n % 10 <= 4 && !(n % 100 >= 12 && n % 100 <= 14) ? "odcinki" : "odcinków"} · żółw: ${where}`;
  }

  async function open(source: string, m: Mode): Promise<RunResult> {
    switchMode(m);
    setSource(source);
    controller.reset();
    controller.finish();
    await viewHost.ready();
    viewHost.fit();
    await painted();
    const s = controller.state;
    return { segments: s.segments, error: s.error };
  }

  // ---- Start --------------------------------------------------------------
  viewHost.setMode(mode);
  editor.value = store.get(draftKey(mode)) ?? "";
  controller.load(editor.value, mode);
  render(controller.state);

  const app: App = {
    open,
    controller,
    destroy() {
      unsubscribe();
      controller.reset();
      viewHost.destroy();
    },
  };
  const hook: LogomocjaHook = { version, run: (src, m) => run(src, m), open };
  (window as unknown as { logomocja: LogomocjaHook }).logomocja = hook;
  return app;
}
