import { run, type Mode, type Segment } from "../lang";
import { fitCamera, flatProjection, isoProjection, paint, readPalette } from "./view2d";

/** Draw a small static picture of a drawing; does nothing where canvas is unavailable. */
export function drawThumbnail(canvas: HTMLCanvasElement, segments: Segment[], mode: Mode) {
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  const width = canvas.clientWidth || 240;
  const height = canvas.clientHeight || 160;
  const dpr = window.devicePixelRatio || 1;
  canvas.width = Math.round(width * dpr);
  canvas.height = Math.round(height * dpr);
  const projection = mode === "3d" ? isoProjection : flatProjection;
  const points = segments.flatMap((s) => [projection(s.from), projection(s.to)]);
  const cam = fitCamera(points.length ? points : [[0, 0]], width, height, 14, 4);
  const palette = readPalette(canvas);
  paint(ctx, { segments, turtle: null }, cam, { width, height, dpr }, palette, {
    projection,
    grid: false,
    origin: false,
    lineScale: 0.7,
  });
}

export function thumbnailFor(source: string, mode: Mode, label: string) {
  const canvas = document.createElement("canvas");
  canvas.className = "thumb";
  canvas.setAttribute("role", "img");
  canvas.setAttribute("aria-label", label);
  const segments = run(source, mode).segments;
  // Draw once the canvas has its laid-out size.
  requestAnimationFrame(() => drawThumbnail(canvas, segments, mode));
  return { canvas, redraw: () => drawThumbnail(canvas, segments, mode) };
}
