import type { Mode } from "../lang";

const toBase64Url = (bytes: Uint8Array) => {
  let bin = "";
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
};

const fromBase64Url = (text: string) => {
  if (!/^[A-Za-z0-9_-]*$/.test(text)) throw new Error("bad base64");
  const bin = atob(text.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((text.length + 3) % 4));
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
};

async function pipe(bytes: Uint8Array, stream: CompressionStream | DecompressionStream): Promise<Uint8Array> {
  const out = new Blob([bytes as BlobPart]).stream().pipeThrough(stream);
  return new Uint8Array(await new Response(out).arrayBuffer());
}

const canCompress = () => typeof CompressionStream !== "undefined" && typeof DecompressionStream !== "undefined";

/** The hash fragment of a permalink: `#/p/<mode>/<z|u><base64url>`; `z` is deflate-compressed UTF-8. */
export async function encodeShare(source: string, mode: Mode): Promise<string> {
  const utf8 = new TextEncoder().encode(source);
  if (canCompress()) {
    try {
      return `#/p/${mode}/z${toBase64Url(await pipe(utf8, new CompressionStream("deflate-raw")))}`;
    } catch {
      // fall through to the uncompressed form
    }
  }
  return `#/p/${mode}/u${toBase64Url(utf8)}`;
}

export const isShareHash = (hash: string) => hash.startsWith("#/p/");

/** Decode a permalink hash; null when it is damaged. */
export async function decodeShare(hash: string): Promise<{ source: string; mode: Mode } | null> {
  const m = /^#\/p\/(2d|3d)\/([zu])([A-Za-z0-9_-]*)$/.exec(hash);
  if (!m) return null;
  try {
    let bytes = fromBase64Url(m[3]);
    if (m[2] === "z") {
      if (!canCompress()) return null;
      bytes = await pipe(bytes, new DecompressionStream("deflate-raw"));
    }
    const source = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
    return { source, mode: m[1] as Mode };
  } catch {
    return null;
  }
}
