import { describe, expect, test } from "bun:test";
import { CHALLENGES, checkChallenge } from "../src/challenges";

const ch = (id: string) => {
  const c = CHALLENGES.find((x) => x.id === id);
  if (!c) throw new Error(`no challenge ${id}`);
  return c;
};

describe("challenges", () => {
  test("there are at least five, each with a task, a mode, and a reference solution that passes", () => {
    expect(CHALLENGES.length).toBeGreaterThanOrEqual(5);
    for (const c of CHALLENGES) {
      expect(c.task.length).toBeGreaterThan(10);
      expect(checkChallenge(c, c.solution)).toEqual({ pass: true, reason: expect.any(String) });
    }
    expect(new Set(CHALLENGES.map((c) => c.id)).size).toBe(CHALLENGES.length);
    expect(CHALLENGES.some((c) => c.mode === "3d")).toBe(true);
  });

  test("the same square drawn another way passes: counter-clockwise, from another corner, in pieces", () => {
    const square = ch("kwadrat");
    expect(checkChallenge(square, "powtorz 4 [np 100 lw 90]").pass).toBe(true);
    expect(checkChallenge(square, "pod np 30 opu powtorz 4 [np 100 pw 90]").pass).toBe(true);
    expect(checkChallenge(square, "powtorz 4 [np 50 np 50 pw 90]").pass).toBe(true);
    expect(checkChallenge(square, "pw 90 powtorz 4 [np 100 lw 90]").pass).toBe(true);
  });

  test("a wrong size fails and says so", () => {
    const result = checkChallenge(ch("kwadrat"), "powtorz 4 [np 80 pw 90]");
    expect(result.pass).toBe(false);
    expect(result.reason).toMatch(/rozmiar/i);
  });

  test("a missing side fails and counts what is missing", () => {
    const result = checkChallenge(ch("kwadrat"), "powtorz 3 [np 100 pw 90]");
    expect(result.pass).toBe(false);
    expect(result.reason).toMatch(/brakuje|odcink/i);
  });

  test("an extra stroke fails", () => {
    expect(checkChallenge(ch("kwadrat"), "powtorz 4 [np 100 pw 90] pw 45 np 141.42").pass).toBe(false);
  });

  test("a program error fails with the error's position and message", () => {
    const result = checkChallenge(ch("kwadrat"), "powtorz 4 [np 100 pw 90");
    expect(result.pass).toBe(false);
    expect(result.reason).toMatch(/wiersz 1/i);
  });

  test("an empty drawing fails", () => {
    expect(checkChallenge(ch("kwadrat"), "; nic").reason).toMatch(/nic/i);
  });

  test("a challenge about colour fails with the right shape in the wrong colour", () => {
    const colourful = CHALLENGES.find((c) => c.checkStyle)!;
    expect(colourful).toBeDefined();
    const wrong = colourful.solution.replace(/"#[0-9a-f]{6}"/gi, '"#000000"');
    const result = checkChallenge(colourful, wrong);
    expect(result.pass).toBe(false);
    expect(result.reason).toMatch(/kolor/i);
  });

  test("a 3D challenge accepts the solid built in another direction", () => {
    const cube = ch("szescian");
    expect(checkChallenge(cube, cube.solution).pass).toBe(true);
    const below = cube.solution.replace(/gora/g, "TMP").replace(/dol/g, "gora").replace(/TMP/g, "dol");
    expect(checkChallenge(cube, below).pass).toBe(true);
  });
});
