input.command:
cat >> tests/app.test.ts <<'EOF'

describe("command reference", () => {
  const COMMANDS = [
    "np", "naprzód", "fd", "ws", "bk", "pw", "rt", "lw", "lt", "pod", "pu", "opu", "pd", "kolor", "color",
    "grubość", "width", "powtórz", "repeat", "niech", "let", "jeśli", "if", "jeżeli", "ifelse", "stop", "dom", "home",
    "czyść", "cs", "góra", "pitchup", "dół", "pitchdown", "pp", "rr", "pl", "rl", "nrpowt", "repcount", "oto", "już",
  ];

  test("documents every command and alias in Polish", async () => {
    mount();
    await navigate("#/polecenia");
    const page = document.querySelector<HTMLElement>(".reference")!;
    expect(page.hidden).toBe(false);
    const codeWords = new Set([...page.querySelectorAll("code")].flatMap((c) => c.textContent!.toLowerCase().split(/[\s,]+/)));
    for (const word of COMMANDS) expect(codeWords).toContain(word);
    for (const heading of ["Wyrażenia", "Zmienne", "Warunki", "Procedury", "Ograniczenia"]) {
      expect([...page.querySelectorAll("h2")].map((h) => h.textContent)).toContain(heading);
    }
  });

  test("every runnable example in the reference works, and Wypróbuj loads it into the studio", async () => {
    const { click } = await import("./dom");
    mount();
    await navigate("#/polecenia");
    const examples = [...document.querySelectorAll<HTMLElement>(".ref-example")];
    expect(examples.length).toBeGreaterThanOrEqual(20);
    for (const ex of examples) {
      const src = ex.querySelector("pre")!.textContent!;
      const mode = ex.dataset.mode as "2d" | "3d";
      const result = run(src, mode);
      if (ex.dataset.expectError) expect(result.error).not.toBeNull();
      else expect({ src, error: result.error }).toEqual({ src, error: null });
    }
    const first = examples.find((e) => e.dataset.mode === "3d")!;
    click(first.querySelector("button")!);
    await new Promise((r) => setTimeout(r, 0));
    expect(location.hash).toBe("#/");
    expect(editor().value).toBe(first.querySelector("pre")!.textContent!);
    expect(control("3D", "button").getAttribute("aria-pressed")).toBe("true");
  });
});
EOF
bun test tests/app.test.ts 2>&1 | grep -E "pass|fail|error:" | head

