input.content:
/* Logomocja — warm paper in light mode, deep green slate in dark mode. */

:root {
  color-scheme: light;
  --bg: #f6f1e6;
  --bg-elev: #fffdf8;
  --bg-sunk: #efe8d9;
  --fg: #1d2b24;
  --fg-muted: #5c6a62;
  --border: #ddd3bf;
  --accent: #16866a;
  --accent-strong: #0f6b54;
  --accent-fg: #ffffff;
  --accent-soft: #d8efe6;
  --warm: #c1763d;
  --warm-soft: #f6e3d2;
  --error: #b3261e;
  --error-soft: #fbe3e0;
  --ok: #1f7a4d;
  --ok-soft: #dcf2e5;
  --focus: #2b6fb3;
  --shadow: 0 1px 2px rgba(60, 50, 30, 0.08), 0 4px 16px rgba(60, 50, 30, 0.06);

  --code-bg: #fffdf8;
  --code-fg: #1d2b24;
  --code-gutter: #9a9384;
  --current-line: rgba(22, 134, 106, 0.14);
  --error-line: rgba(179, 38, 30, 0.08);
  --t-comment: #8a8270;
  --t-string: #a14d12;
  --t-number: #b0522c;
  --t-keyword: #0f6b54;
  --t-value: #7b3fa0;
  --t-proc: #2b5fa3;
  --t-name: #1d2b24;
  --t-bracket: #8a6d1d;
  --t-op: #5c6a62;

  --canvas-bg: #fffdf8;
  --canvas-grid: rgba(60, 50, 30, 0.07);
  --canvas-axis: rgba(60, 50, 30, 0.28);
  --canvas-origin: #c1763d;
  --canvas-turtle: #1d2b24;

  --radius: 12px;
  --radius-sm: 8px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", Ubuntu, Cantarell, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "Cascadia Code", "JetBrains Mono", "SF Mono", Menlo, Consolas, "DejaVu Sans Mono", "Liberation Mono", monospace;
  --header-h: 56px;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --bg: #101a17;
    --bg-elev: #17241f;
    --bg-sunk: #0c1412;
    --fg: #e5eee9;
    --fg-muted: #9db0a6;
    --border: #2b3d36;
    --accent: #3cc39c;
    --accent-strong: #5fd6b2;
    --accent-fg: #06261d;
    --accent-soft: #173a30;
    --warm: #e8a46a;
    --warm-soft: #3a2a1c;
    --error: #ff8a80;
    --error-soft: #3d1f1c;
    --ok: #6fdc9f;
    --ok-soft: #173326;
    --focus: #7fb5ff;
    --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 6px 20px rgba(0, 0, 0, 0.25);
    --code-bg: #131f1b;
    --code-fg: #e5eee9;
    --code-gutter: #61766d;
    --current-line: rgba(60, 195, 156, 0.16);
    --error-line: rgba(255, 138, 128, 0.1);
    --t-comment: #7d8f86;
    --t-string: #f0b37e;
    --t-number: #f49b74;
    --t-keyword: #5fd6b2;
    --t-value: #d2a8ff;
    --t-proc: #8cb8ff;
    --t-name: #e5eee9;
    --t-bracket: #e3c56b;
    --t-op: #9db0a6;
    --canvas-bg: #131f1b;
    --canvas-grid: rgba(220, 240, 230, 0.06);
    --canvas-axis: rgba(220, 240, 230, 0.25);
    --canvas-origin: #e8a46a;
    --canvas-turtle: #e5eee9;
  }
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #101a17;
  --bg-elev: #17241f;
  --bg-sunk: #0c1412;
  --fg: #e5eee9;
  --fg-muted: #9db0a6;
  --border: #2b3d36;
  --accent: #3cc39c;
  --accent-strong: #5fd6b2;
  --accent-fg: #06261d;
  --accent-soft: #173a30;
  --warm: #e8a46a;
  --warm-soft: #3a2a1c;
  --error: #ff8a80;
  --error-soft: #3d1f1c;
  --ok: #6fdc9f;
  --ok-soft: #173326;
  --focus: #7fb5ff;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 6px 20px rgba(0, 0, 0, 0.25);
  --code-bg: #131f1b;
  --code-fg: #e5eee9;
  --code-gutter: #61766d;
  --current-line: rgba(60, 195, 156, 0.16);
  --error-line: rgba(255, 138, 128, 0.1);
  --t-comment: #7d8f86;
  --t-string: #f0b37e;
  --t-number: #f49b74;
  --t-keyword: #5fd6b2;
  --t-value: #d2a8ff;
  --t-proc: #8cb8ff;
  --t-name: #e5eee9;
  --t-bracket: #e3c56b;
  --t-op: #9db0a6;
  --canvas-bg: #131f1b;
  --canvas-grid: rgba(220, 240, 230, 0.06);
  --canvas-axis: rgba(220, 240, 230, 0.25);
  --canvas-origin: #e8a46a;
  --canvas-turtle: #e5eee9;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  -webkit-text-size-adjust: 100%;
}

body {
  min-height: 100dvh;
}

[hidden] {
  display: none !important;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -60px;
  z-index: 100;
  background: var(--accent);
  color: var(--accent-fg);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  text-decoration: none;
  font-weight: 600;
}
.skip-link:focus {
  top: 8px;
}

a {
  color: var(--accent-strong);
}

kbd {
  font-family: var(--mono);
  font-size: 0.85em;
  background: var(--bg-sunk);
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-radius: 6px;
  padding: 1px 6px;
  white-space: nowrap;
}

code {
  font-family: var(--mono);
  font-size: 0.92em;
}

.icon {
  width: 20px;
  height: 20px;
  flex: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
}
.icon path[fill] {
  stroke: none;
}

/* ---- Layout ------------------------------------------------------------ */

.app {
  min-height: 100dvh;
  display: grid;
  grid-template-rows: auto 1fr;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 12px 18px;
  flex-wrap: wrap;
  padding: 8px max(16px, env(safe-area-inset-right)) 8px max(16px, env(safe-area-inset-left));
  min-height: var(--header-h);
  background: color-mix(in srgb, var(--bg) 88%, transparent);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  font-size: 1.15rem;
  letter-spacing: -0.01em;
  color: var(--fg);
  text-decoration: none;
}
.brand-mark {
  display: inline-grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 9px;
  background: var(--accent);
  color: var(--accent-fg);
  font-size: 14px;
  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.15);
}

.nav {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}
.nav-link {
  padding: 6px 12px;
  border-radius: 999px;
  color: var(--fg-muted);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
}
.nav-link:hover {
  color: var(--fg);
  background: var(--bg-sunk);
}
.nav-link[aria-current="page"] {
  color: var(--accent-strong);
  background: var(--accent-soft);
}

.mode-switch {
  display: inline-flex;
  padding: 3px;
  border-radius: 999px;
  background: var(--bg-sunk);
  border: 1px solid var(--border);
  margin-left: auto;
}
.mode-btn {
  font: inherit;
  font-weight: 700;
  font-size: 0.9rem;
  border: 0;
  background: transparent;
  color: var(--fg-muted);
  padding: 4px 14px;
  border-radius: 999px;
  cursor: pointer;
  min-height: 32px;
}
.mode-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--accent-fg);
  box-shadow: var(--shadow);
}
.mode-btn:disabled {
  cursor: not-allowed;
  opacity: 0.75;
}

.topbar-actions {
  display: flex;
  gap: 4px;
}

.icon-btn {
  display: inline-grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--fg);
  cursor: pointer;
}
.icon-btn:hover {
  background: var(--bg-sunk);
  border-color: var(--border);
}
.icon-btn.small {
  width: 30px;
  height: 30px;
}

main {
  min-width: 0;
}

/* ---- Buttons ------------------------------------------------------------ */

.btn,
.tool {
  font: inherit;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--bg-elev);
  color: var(--fg);
  cursor: pointer;
  font-weight: 600;
  white-space: nowrap;
  min-height: 38px;
  padding: 6px 12px;
}
.btn:hover,
.tool:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
  background: color-mix(in srgb, var(--accent-soft) 45%, var(--bg-elev));
}
.btn.primary,
.tool.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-fg);
}
.btn.primary:hover,
.tool.primary:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}
.btn.small {
  min-height: 30px;
  padding: 3px 10px;
  font-size: 0.9rem;
}
.tool:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.tool.small {
  min-height: 32px;
  padding: 4px 10px;
  font-size: 0.88rem;
  font-weight: 600;
}
.tool.small .icon {
  width: 17px;
  height: 17px;
}
.link {
  font: inherit;
  background: none;
  border: 0;
  padding: 0 2px;
  color: var(--accent-strong);
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
  font-weight: 600;
}

/* ---- Studio ------------------------------------------------------------- */

.studio {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px max(12px, env(safe-area-inset-right)) 12px max(12px, env(safe-area-inset-left));
  height: calc(100dvh - var(--header-h));
  min-height: 560px;
}

.workspace {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(340px, 1fr) minmax(0, 1.35fr);
  gap: 12px;
}

.pane {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 10px;
}

.toolbar,
.filebar {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}
.filebar {
  padding-top: 2px;
}

.speed {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  font-size: 0.9rem;
  color: var(--fg-muted);
  font-weight: 600;
}
.speed input {
  width: 110px;
  accent-color: var(--accent);
}

/* ---- Editor ------------------------------------------------------------- */

.editor {
  --line: 1.6em;
  position: relative;
  flex: 1;
  min-height: 180px;
  display: flex;
  font-family: var(--mono);
  font-size: 14.5px;
  line-height: var(--line);
  background: var(--code-bg);
  color: var(--code-fg);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  overflow: hidden;
}
.editor:focus-within {
  outline: 3px solid var(--focus);
  outline-offset: 1px;
}
.editor-gutter {
  flex: none;
  min-width: 3.4em;
  padding: 10px 8px 10px 4px;
  text-align: right;
  color: var(--code-gutter);
  background: color-mix(in srgb, var(--bg-sunk) 55%, var(--code-bg));
  border-right: 1px solid var(--border);
  user-select: none;
  will-change: transform;
}
.editor-gutter .line {
  height: var(--line);
  position: relative;
  padding-left: 1.2em;
}
.editor-gutter .line.is-current {
  color: var(--accent-strong);
  font-weight: 700;
}
.editor-gutter .line.is-error {
  color: var(--error);
  font-weight: 700;
}
.gutter-mark {
  position: absolute;
  left: 2px;
  font-size: 0.8em;
}
.editor-scroller {
  position: relative;
  flex: 1;
  min-width: 0;
  overflow: hidden;
}
.editor-code,
.editor-input {
  margin: 0;
  padding: 10px 14px 40px;
  font: inherit;
  line-height: inherit;
  white-space: pre;
  tab-size: 2;
  letter-spacing: 0;
  word-spacing: 0;
}
.editor-code {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  pointer-events: none;
  will-change: transform;
}
.editor-code .line {
  height: var(--line);
  margin: 0 -14px;
  padding: 0 14px;
}
.editor-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  resize: none;
  border: 0;
  outline: none;
  background: transparent;
  color: transparent;
  caret-color: var(--fg);
  overflow: auto;
  -webkit-text-fill-color: transparent;
}
.editor-input::selection {
  background: color-mix(in srgb, var(--focus) 30%, transparent);
  -webkit-text-fill-color: transparent;
}
.line.is-current {
  background: var(--current-line);
}
.line.is-error {
  background: var(--error-line);
}
.t-comment {
  color: var(--t-comment);
  font-style: italic;
}
.t-string {
  color: var(--t-string);
}
.t-number {
  color: var(--t-number);
}
.t-keyword {
  color: var(--t-keyword);
  font-weight: 700;
}
.t-value {
  color: var(--t-value);
  font-weight: 600;
}
.t-proc {
  color: var(--t-proc);
  font-weight: 600;
}
.t-name {
  color: var(--t-name);
}
.t-bracket {
  color: var(--t-bracket);
  font-weight: 700;
}
.t-paren,
.t-op {
  color: var(--t-op);
}
.t-error {
  text-decoration: wavy underline var(--error);
  text-decoration-skip-ink: none;
  text-underline-offset: 4px;
  background: color-mix(in srgb, var(--error) 14%, transparent);
  border-radius: 2px;
}
.inline-error {
  color: var(--error);
  font-family: var(--font);
  font-size: 0.86em;
  font-weight: 600;
}

.error-box {
  border-radius: var(--radius-sm);
  background: var(--error-soft);
  color: var(--fg);
  border: 1px solid color-mix(in srgb, var(--error) 40%, transparent);
  padding: 8px 12px;
  font-size: 0.93rem;
}
.error-box strong {
  color: var(--error);
}

/* ---- View --------------------------------------------------------------- */

.view-pane {
  padding: 0;
  overflow: hidden;
  gap: 0;
}
.viewhost {
  position: relative;
  flex: 1;
  min-height: 260px;
  display: flex;
  flex-direction: column;
}
.stage {
  position: relative;
  flex: 1;
  min-height: 0;
}
.view2d,
.view3d {
  position: absolute;
  inset: 0;
}
.view-canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
  background: var(--canvas-bg);
}
.view-canvas:active {
  cursor: grabbing;
}
.view-canvas:focus-visible {
  outline-offset: -4px;
}
.view-controls {
  position: absolute;
  top: 10px;
  right: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  z-index: 2;
}
.view-controls .tool {
  width: 38px;
  height: 38px;
  padding: 0;
  box-shadow: var(--shadow);
}
.view-hint {
  position: absolute;
  left: 12px;
  bottom: 8px;
  margin: 0;
  max-width: calc(100% - 24px);
  font-size: 0.78rem;
  color: var(--fg-muted);
  pointer-events: none;
}
.notice {
  margin: 10px;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  background: var(--warm-soft);
  border: 1px solid color-mix(in srgb, var(--warm) 45%, transparent);
  font-size: 0.92rem;
  z-index: 1;
}
.statusbar {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 4px 12px;
  padding: 8px 12px;
  border-top: 1px solid var(--border);
  font-size: 0.88rem;
  color: var(--fg-muted);
  background: var(--bg-elev);
}
.status-text {
  font-weight: 700;
  color: var(--fg);
}

/* ---- Challenge panel ---------------------------------------------------- */

.challenge-panel {
  display: flex;
  gap: 14px;
  align-items: stretch;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-left: 5px solid var(--warm);
  border-radius: var(--radius);
  padding: 10px 14px;
  box-shadow: var(--shadow);
}
.challenge-panel h2 {
  margin: 0 0 2px;
  font-size: 1.1rem;
}
.challenge-task {
  margin: 0 0 4px;
  font-weight: 600;
}
.challenge-panel details {
  font-size: 0.92rem;
  color: var(--fg-muted);
}
.challenge-panel details p {
  margin: 4px 0;
}
.challenge-panel summary {
  cursor: pointer;
  font-weight: 600;
}
.challenge-info {
  flex: 1;
  min-width: 0;
}
.challenge-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}
.challenge-target {
  position: relative;
  flex: none;
  width: 150px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  border: 1px solid var(--border);
  background: var(--canvas-bg);
}
.challenge-target .thumb {
  width: 100%;
  height: 100%;
  min-height: 110px;
}
.challenge-target .caption {
  position: absolute;
  left: 6px;
  top: 4px;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--fg-muted);
}
.challenge-result {
  margin: 8px 0 0;
  font-weight: 600;
}
.challenge-result:empty {
  display: none;
}
.challenge-result.is-pass {
  color: var(--ok);
  background: var(--ok-soft);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
}
.challenge-result.is-fail {
  color: var(--error);
  background: var(--error-soft);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
}

/* ---- Pages -------------------------------------------------------------- */

.page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 24px max(16px, env(safe-area-inset-right)) 64px max(16px, env(safe-area-inset-left));
}
.page h1 {
  font-size: clamp(1.7rem, 3vw, 2.3rem);
  letter-spacing: -0.02em;
  margin: 8px 0 6px;
}
.lead {
  color: var(--fg-muted);
  max-width: 70ch;
  font-size: 1.05rem;
}

.card-grid {
  list-style: none;
  padding: 0;
  margin: 12px 0 28px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 14px;
}
.card {
  display: flex;
  flex-direction: column;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}
.card .thumb {
  display: block;
  width: 100%;
  height: 160px;
  background: var(--canvas-bg);
  border-bottom: 1px solid var(--border);
}
.card-body {
  padding: 10px 14px 4px;
  flex: 1;
}
.card-body h3 {
  margin: 0 0 4px;
  font-size: 1.05rem;
}
.card-body p {
  margin: 0 0 6px;
  color: var(--fg-muted);
  font-size: 0.93rem;
}
.card > .btn {
  margin: 4px 14px 14px;
}
.badge {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  padding: 1px 7px;
  border-radius: 999px;
  vertical-align: middle;
  background: var(--accent-soft);
  color: var(--accent-strong);
}
.challenge-card .state {
  font-weight: 700;
  color: var(--fg-muted);
}
.challenge-card .state.ok {
  color: var(--ok);
}
.challenge-card.is-passed {
  border-color: color-mix(in srgb, var(--ok) 45%, var(--border));
}
.challenge-progress {
  font-weight: 700;
  display: inline-block;
  background: var(--warm-soft);
  padding: 4px 12px;
  border-radius: 999px;
}

/* Reference */

.reference {
  max-width: 900px;
}
.toc ul {
  list-style: none;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  margin: 10px 0 18px;
}
.ref-section {
  border-top: 1px solid var(--border);
  padding-top: 8px;
  margin-top: 22px;
  scroll-margin-top: calc(var(--header-h) + 10px);
}
.ref-section h2 {
  font-size: 1.45rem;
  margin: 10px 0 6px;
}
.ref-section > p {
  max-width: 72ch;
}
.ref-entry {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 10px 16px 12px;
  margin: 12px 0;
}
.ref-entry h3 {
  margin: 2px 0 4px;
  font-size: 1.08rem;
}
.ref-entry h3 code {
  color: var(--t-keyword);
}
.ref-entry .en {
  font-weight: 500;
  color: var(--fg-muted);
  font-size: 0.92rem;
}
.ref-entry .en code {
  color: var(--fg-muted);
}
.ref-entry p {
  margin: 4px 0;
}
.arg {
  font-size: 0.93rem;
  color: var(--fg-muted);
}
.ref-example {
  margin: 10px 0 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--code-bg);
}
.ref-example pre {
  margin: 0;
  padding: 10px 14px;
  overflow-x: auto;
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1.55;
}
.ref-example figcaption {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 10px;
  border-top: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-sunk) 50%, var(--code-bg));
  font-size: 0.88rem;
}
.ref-example figcaption .btn {
  margin-left: auto;
}
.ref-example .note {
  color: var(--error);
  font-weight: 600;
}
table.limits,
table.shortcuts {
  border-collapse: collapse;
  width: 100%;
  margin: 8px 0;
  font-size: 0.95rem;
}
table.limits th,
table.limits td,
table.shortcuts th,
table.shortcuts td {
  text-align: left;
  padding: 7px 10px;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}
table.limits thead th {
  color: var(--fg-muted);
  font-size: 0.85rem;
}
table.limits tbody th,
table.shortcuts th {
  font-weight: 500;
}
table.shortcuts th {
  width: 40%;
}

/* ---- Dialogs and toast --------------------------------------------------- */

.dialog {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-elev);
  color: var(--fg);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
  padding: 18px 22px;
  width: min(560px, calc(100vw - 24px));
}
.dialog::backdrop {
  background: rgba(10, 20, 15, 0.45);
}
.dialog h2 {
  margin: 0 0 8px;
  font-size: 1.25rem;
}
.dialog form {
  margin: 0;
}
.dialog-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  margin-top: 12px;
}
.dialog > form:last-child {
  display: flex;
  justify-content: flex-end;
  margin-top: 12px;
}
.share-field {
  width: 100%;
  font: inherit;
  font-family: var(--mono);
  font-size: 0.85rem;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--code-bg);
  color: var(--fg);
  margin-top: 4px;
}
.hint {
  color: var(--fg-muted);
  font-size: 0.9rem;
  min-height: 1.4em;
  margin: 6px 0 0;
}

.toast {
  position: fixed;
  left: 50%;
  bottom: max(16px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: min(640px, calc(100vw - 24px));
  padding: 8px 8px 8px 16px;
  border-radius: 999px;
  background: var(--fg);
  color: var(--bg);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
  font-size: 0.93rem;
}
.toast .link {
  color: var(--bg);
}
.toast .icon-btn {
  color: var(--bg);
}
.toast .icon-btn:hover {
  background: color-mix(in srgb, var(--bg) 18%, transparent);
  border-color: transparent;
}

/* ---- Small screens ------------------------------------------------------- */

@media (max-width: 900px) {
  .studio {
    height: auto;
    min-height: 0;
  }
  .workspace {
    grid-template-columns: 1fr;
  }
  .editor {
    min-height: 260px;
    max-height: 48vh;
  }
  .viewhost {
    min-height: 58vh;
  }
}

@media (max-width: 640px) {
  .topbar {
    gap: 6px 10px;
    padding-top: 6px;
    padding-bottom: 6px;
  }
  .nav {
    order: 5;
    width: 100%;
    justify-content: space-between;
  }
  .nav-link {
    padding: 5px 10px;
    font-size: 0.9rem;
  }
  .mode-switch {
    margin-left: auto;
  }
  .studio {
    padding: 8px;
  }
  .pane {
    padding: 8px;
  }
  .toolbar .tool {
    flex: 1 1 auto;
    padding: 6px 8px;
  }
  .speed {
    width: 100%;
    margin-left: 0;
  }
  .speed input {
    flex: 1;
  }
  .filebar .tool .tool-label {
    font-size: 0.82rem;
  }
  .challenge-panel {
    flex-direction: column;
  }
  .challenge-target {
    width: 100%;
    height: 130px;
  }
  .view-hint {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    scroll-behavior: auto !important;
    transition: none !important;
  }
}

toolu_01Hg1q3g2jTjqA6oLCFkaCYc.content:
/* Logomocja — warm paper in light mode, deep green slate in dark mode. */

:root {
  color-scheme: light;
  --bg: #f6f1e6;
  --bg-elev: #fffdf8;
  --bg-sunk: #efe8d9;
  --fg: #1d2b24;
  --fg-muted: #5c6a62;
  --border: #ddd3bf;
  --accent: #16866a;
  --accent-strong: #0f6b54;
  --accent-fg: #ffffff;
  --accent-soft: #d8efe6;
  --warm: #c1763d;
  --warm-soft: #f6e3d2;
  --error: #b3261e;
  --error-soft: #fbe3e0;
  --ok: #1f7a4d;
  --ok-soft: #dcf2e5;
  --focus: #2b6fb3;
  --shadow: 0 1px 2px rgba(60, 50, 30, 0.08), 0 4px 16px rgba(60, 50, 30, 0.06);

  --code-bg: #fffdf8;
  --code-fg: #1d2b24;
  --code-gutter: #9a9384;
  --current-line: rgba(22, 134, 106, 0.14);
  --error-line: rgba(179, 38, 30, 0.08);
  --t-comment: #8a8270;
  --t-string: #a14d12;
  --t-number: #b0522c;
  --t-keyword: #0f6b54;
  --t-value: #7b3fa0;
  --t-proc: #2b5fa3;
  --t-name: #1d2b24;
  --t-bracket: #8a6d1d;
  --t-op: #5c6a62;

  --canvas-bg: #fffdf8;
  --canvas-grid: rgba(60, 50, 30, 0.07);
  --canvas-axis: rgba(60, 50, 30, 0.28);
  --canvas-origin: #c1763d;
  --canvas-turtle: #1d2b24;

  --radius: 12px;
  --radius-sm: 8px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", Ubuntu, Cantarell, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "Cascadia Code", "JetBrains Mono", "SF Mono", Menlo, Consolas, "DejaVu Sans Mono", "Liberation Mono", monospace;
  --header-h: 56px;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --bg: #101a17;
    --bg-elev: #17241f;
    --bg-sunk: #0c1412;
    --fg: #e5eee9;
    --fg-muted: #9db0a6;
    --border: #2b3d36;
    --accent: #3cc39c;
    --accent-strong: #5fd6b2;
    --accent-fg: #06261d;
    --accent-soft: #173a30;
    --warm: #e8a46a;
    --warm-soft: #3a2a1c;
    --error: #ff8a80;
    --error-soft: #3d1f1c;
    --ok: #6fdc9f;
    --ok-soft: #173326;
    --focus: #7fb5ff;
    --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 6px 20px rgba(0, 0, 0, 0.25);
    --code-bg: #131f1b;
    --code-fg: #e5eee9;
    --code-gutter: #61766d;
    --current-line: rgba(60, 195, 156, 0.16);
    --error-line: rgba(255, 138, 128, 0.1);
    --t-comment: #7d8f86;
    --t-string: #f0b37e;
    --t-number: #f49b74;
    --t-keyword: #5fd6b2;
    --t-value: #d2a8ff;
    --t-proc: #8cb8ff;
    --t-name: #e5eee9;
    --t-bracket: #e3c56b;
    --t-op: #9db0a6;
    --canvas-bg: #131f1b;
    --canvas-grid: rgba(220, 240, 230, 0.06);
    --canvas-axis: rgba(220, 240, 230, 0.25);
    --canvas-origin: #e8a46a;
    --canvas-turtle: #e5eee9;
  }
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #101a17;
  --bg-elev: #17241f;
  --bg-sunk: #0c1412;
  --fg: #e5eee9;
  --fg-muted: #9db0a6;
  --border: #2b3d36;
  --accent: #3cc39c;
  --accent-strong: #5fd6b2;
  --accent-fg: #06261d;
  --accent-soft: #173a30;
  --warm: #e8a46a;
  --warm-soft: #3a2a1c;
  --error: #ff8a80;
  --error-soft: #3d1f1c;
  --ok: #6fdc9f;
  --ok-soft: #173326;
  --focus: #7fb5ff;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 6px 20px rgba(0, 0, 0, 0.25);
  --code-bg: #131f1b;
  --code-fg: #e5eee9;
  --code-gutter: #61766d;
  --current-line: rgba(60, 195, 156, 0.16);
  --error-line: rgba(255, 138, 128, 0.1);
  --t-comment: #7d8f86;
  --t-string: #f0b37e;
  --t-number: #f49b74;
  --t-keyword: #5fd6b2;
  --t-value: #d2a8ff;
  --t-proc: #8cb8ff;
  --t-name: #e5eee9;
  --t-bracket: #e3c56b;
  --t-op: #9db0a6;
  --canvas-bg: #131f1b;
  --canvas-grid: rgba(220, 240, 230, 0.06);
  --canvas-axis: rgba(220, 240, 230, 0.25);
  --canvas-origin: #e8a46a;
  --canvas-turtle: #e5eee9;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  -webkit-text-size-adjust: 100%;
}

body {
  min-height: 100dvh;
}

[hidden] {
  display: none !important;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -60px;
  z-index: 100;
  background: var(--accent);
  color: var(--accent-fg);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  text-decoration: none;
  font-weight: 600;
}
.skip-link:focus {
  top: 8px;
}

a {
  color: var(--accent-strong);
}

kbd {
  font-family: var(--mono);
  font-size: 0.85em;
  background: var(--bg-sunk);
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-radius: 6px;
  padding: 1px 6px;
  white-space: nowrap;
}

code {
  font-family: var(--mono);
  font-size: 0.92em;
}

.icon {
  width: 20px;
  height: 20px;
  flex: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
}
.icon path[fill] {
  stroke: none;
}

/* ---- Layout ------------------------------------------------------------ */

.app {
  min-height: 100dvh;
  display: grid;
  grid-template-rows: auto 1fr;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 12px 18px;
  flex-wrap: wrap;
  padding: 8px max(16px, env(safe-area-inset-right)) 8px max(16px, env(safe-area-inset-left));
  min-height: var(--header-h);
  background: color-mix(in srgb, var(--bg) 88%, transparent);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  font-size: 1.15rem;
  letter-spacing: -0.01em;
  color: var(--fg);
  text-decoration: none;
}
.brand-mark {
  display: inline-grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 9px;
  background: var(--accent);
  color: var(--accent-fg);
  font-size: 14px;
  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.15);
}

.nav {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}
.nav-link {
  padding: 6px 12px;
  border-radius: 999px;
  color: var(--fg-muted);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
}
.nav-link:hover {
  color: var(--fg);
  background: var(--bg-sunk);
}
.nav-link[aria-current="page"] {
  color: var(--accent-strong);
  background: var(--accent-soft);
}

.mode-switch {
  display: inline-flex;
  padding: 3px;
  border-radius: 999px;
  background: var(--bg-sunk);
  border: 1px solid var(--border);
  margin-left: auto;
}
.mode-btn {
  font: inherit;
  font-weight: 700;
  font-size: 0.9rem;
  border: 0;
  background: transparent;
  color: var(--fg-muted);
  padding: 4px 14px;
  border-radius: 999px;
  cursor: pointer;
  min-height: 32px;
}
.mode-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--accent-fg);
  box-shadow: var(--shadow);
}
.mode-btn:disabled {
  cursor: not-allowed;
  opacity: 0.75;
}

.topbar-actions {
  display: flex;
  gap: 4px;
}

.icon-btn {
  display: inline-grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--fg);
  cursor: pointer;
}
.icon-btn:hover {
  background: var(--bg-sunk);
  border-color: var(--border);
}
.icon-btn.small {
  width: 30px;
  height: 30px;
}

main {
  min-width: 0;
}

/* ---- Buttons ------------------------------------------------------------ */

.btn,
.tool {
  font: inherit;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--bg-elev);
  color: var(--fg);
  cursor: pointer;
  font-weight: 600;
  white-space: nowrap;
  min-height: 38px;
  padding: 6px 12px;
}
.btn:hover,
.tool:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
  background: color-mix(in srgb, var(--accent-soft) 45%, var(--bg-elev));
}
.btn.primary,
.tool.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-fg);
}
.btn.primary:hover,
.tool.primary:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}
.btn.small {
  min-height: 30px;
  padding: 3px 10px;
  font-size: 0.9rem;
}
.tool:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.tool.small {
  min-height: 32px;
  padding: 4px 10px;
  font-size: 0.88rem;
  font-weight: 600;
}
.tool.small .icon {
  width: 17px;
  height: 17px;
}
.link {
  font: inherit;
  background: none;
  border: 0;
  padding: 0 2px;
  color: var(--accent-strong);
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
  font-weight: 600;
}

/* ---- Studio ------------------------------------------------------------- */

.studio {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px max(12px, env(safe-area-inset-right)) 12px max(12px, env(safe-area-inset-left));
  height: calc(100dvh - var(--header-h));
  min-height: 560px;
}

.workspace {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(340px, 1fr) minmax(0, 1.35fr);
  gap: 12px;
}

.pane {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 10px;
}

.toolbar,
.filebar {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}
.filebar {
  padding-top: 2px;
}

.speed {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  font-size: 0.9rem;
  color: var(--fg-muted);
  font-weight: 600;
}
.speed input {
  width: 110px;
  accent-color: var(--accent);
}

/* ---- Editor ------------------------------------------------------------- */

.editor {
  --line: 1.6em;
  position: relative;
  flex: 1;
  min-height: 180px;
  display: flex;
  font-family: var(--mono);
  font-size: 14.5px;
  line-height: var(--line);
  background: var(--code-bg);
  color: var(--code-fg);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  overflow: hidden;
}
.editor:focus-within {
  outline: 3px solid var(--focus);
  outline-offset: 1px;
}
.editor-gutter {
  flex: none;
  min-width: 3.4em;
  padding: 10px 8px 10px 4px;
  text-align: right;
  color: var(--code-gutter);
  background: color-mix(in srgb, var(--bg-sunk) 55%, var(--code-bg));
  border-right: 1px solid var(--border);
  user-select: none;
  will-change: transform;
}
.editor-gutter .line {
  height: var(--line);
  position: relative;
  padding-left: 1.2em;
}
.editor-gutter .line.is-current {
  color: var(--accent-strong);
  font-weight: 700;
}
.editor-gutter .line.is-error {
  color: var(--error);
  font-weight: 700;
}
.gutter-mark {
  position: absolute;
  left: 2px;
  font-size: 0.8em;
}
.editor-scroller {
  position: relative;
  flex: 1;
  min-width: 0;
  overflow: hidden;
}
.editor-code,
.editor-input {
  margin: 0;
  padding: 10px 14px 40px;
  font: inherit;
  line-height: inherit;
  white-space: pre;
  tab-size: 2;
  letter-spacing: 0;
  word-spacing: 0;
}
.editor-code {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  pointer-events: none;
  will-change: transform;
}
.editor-code .line {
  height: var(--line);
  margin: 0 -14px;
  padding: 0 14px;
}
.editor-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  resize: none;
  border: 0;
  outline: none;
  background: transparent;
  color: transparent;
  caret-color: var(--fg);
  overflow: auto;
  -webkit-text-fill-color: transparent;
}
.editor-input::selection {
  background: color-mix(in srgb, var(--focus) 30%, transparent);
  -webkit-text-fill-color: transparent;
}
.line.is-current {
  background: var(--current-line);
}
.line.is-error {
  background: var(--error-line);
}
.t-comment {
  color: var(--t-comment);
  font-style: italic;
}
.t-string {
  color: var(--t-string);
}
.t-number {
  color: var(--t-number);
}
.t-keyword {
  color: var(--t-keyword);
  font-weight: 700;
}
.t-value {
  color: var(--t-value);
  font-weight: 600;
}
.t-proc {
  color: var(--t-proc);
  font-weight: 600;
}
.t-name {
  color: var(--t-name);
}
.t-bracket {
  color: var(--t-bracket);
  font-weight: 700;
}
.t-paren,
.t-op {
  color: var(--t-op);
}
.t-error {
  text-decoration: wavy underline var(--error);
  text-decoration-skip-ink: none;
  text-underline-offset: 4px;
  background: color-mix(in srgb, var(--error) 14%, transparent);
  border-radius: 2px;
}
.inline-error {
  color: var(--error);
  font-family: var(--font);
  font-size: 0.86em;
  font-weight: 600;
}

.error-box {
  border-radius: var(--radius-sm);
  background: var(--error-soft);
  color: var(--fg);
  border: 1px solid color-mix(in srgb, var(--error) 40%, transparent);
  padding: 8px 12px;
  font-size: 0.93rem;
}
.error-box strong {
  color: var(--error);
}

/* ---- View --------------------------------------------------------------- */

.view-pane {
  padding: 0;
  overflow: hidden;
  gap: 0;
}
.viewhost {
  position: relative;
  flex: 1;
  min-height: 260px;
  display: flex;
  flex-direction: column;
}
.stage {
  position: relative;
  flex: 1;
  min-height: 0;
}
.view2d,
.view3d {
  position: absolute;
  inset: 0;
}
.view-canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
  background: var(--canvas-bg);
}
.view-canvas:active {
  cursor: grabbing;
}
.view-canvas:focus-visible {
  outline-offset: -4px;
}
.view-controls {
  position: absolute;
  top: 10px;
  right: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  z-index: 2;
}
.view-controls .tool {
  width: 38px;
  height: 38px;
  padding: 0;
  box-shadow: var(--shadow);
}
.view-hint {
  position: absolute;
  left: 12px;
  bottom: 8px;
  margin: 0;
  max-width: calc(100% - 24px);
  font-size: 0.78rem;
  color: var(--fg-muted);
  pointer-events: none;
}
.notice {
  margin: 10px;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  background: var(--warm-soft);
  border: 1px solid color-mix(in srgb, var(--warm) 45%, transparent);
  font-size: 0.92rem;
  z-index: 1;
}
.statusbar {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 4px 12px;
  padding: 8px 12px;
  border-top: 1px solid var(--border);
  font-size: 0.88rem;
  color: var(--fg-muted);
  background: var(--bg-elev);
}
.status-text {
  font-weight: 700;
  color: var(--fg);
}

/* ---- Challenge panel ---------------------------------------------------- */

.challenge-panel {
  display: flex;
  gap: 14px;
  align-items: stretch;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-left: 5px solid var(--warm);
  border-radius: var(--radius);
  padding: 10px 14px;
  box-shadow: var(--shadow);
}
.challenge-panel h2 {
  margin: 0 0 2px;
  font-size: 1.1rem;
}
.challenge-task {
  margin: 0 0 4px;
  font-weight: 600;
}
.challenge-panel details {
  font-size: 0.92rem;
  color: var(--fg-muted);
}
.challenge-panel details p {
  margin: 4px 0;
}
.challenge-panel summary {
  cursor: pointer;
  font-weight: 600;
}
.challenge-info {
  flex: 1;
  min-width: 0;
}
.challenge-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}
.challenge-target {
  position: relative;
  flex: none;
  width: 150px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  border: 1px solid var(--border);
  background: var(--canvas-bg);
}
.challenge-target .thumb {
  width: 100%;
  height: 100%;
  min-height: 110px;
}
.challenge-target .caption {
  position: absolute;
  left: 6px;
  top: 4px;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--fg-muted);
}
.challenge-result {
  margin: 8px 0 0;
  font-weight: 600;
}
.challenge-result:empty {
  display: none;
}
.challenge-result.is-pass {
  color: var(--ok);
  background: var(--ok-soft);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
}
.challenge-result.is-fail {
  color: var(--error);
  background: var(--error-soft);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
}

/* ---- Pages -------------------------------------------------------------- */

.page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 24px max(16px, env(safe-area-inset-right)) 64px max(16px, env(safe-area-inset-left));
}
.page h1 {
  font-size: clamp(1.7rem, 3vw, 2.3rem);
  letter-spacing: -0.02em;
  margin: 8px 0 6px;
}
.lead {
  color: var(--fg-muted);
  max-width: 70ch;
  font-size: 1.05rem;
}

.card-grid {
  list-style: none;
  padding: 0;
  margin: 12px 0 28px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 14px;
}
.card {
  display: flex;
  flex-direction: column;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}
.card .thumb {
  display: block;
  width: 100%;
  height: 160px;
  background: var(--canvas-bg);
  border-bottom: 1px solid var(--border);
}
.card-body {
  padding: 10px 14px 4px;
  flex: 1;
}
.card-body h3 {
  margin: 0 0 4px;
  font-size: 1.05rem;
}
.card-body p {
  margin: 0 0 6px;
  color: var(--fg-muted);
  font-size: 0.93rem;
}
.card > .btn {
  margin: 4px 14px 14px;
}
.badge {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  padding: 1px 7px;
  border-radius: 999px;
  vertical-align: middle;
  background: var(--accent-soft);
  color: var(--accent-strong);
}
.challenge-card .state {
  font-weight: 700;
  color: var(--fg-muted);
}
.challenge-card .state.ok {
  color: var(--ok);
}
.challenge-card.is-passed {
  border-color: color-mix(in srgb, var(--ok) 45%, var(--border));
}
.challenge-progress {
  font-weight: 700;
  display: inline-block;
  background: var(--warm-soft);
  padding: 4px 12px;
  border-radius: 999px;
}

/* Reference */

.reference {
  max-width: 900px;
}
.toc ul {
  list-style: none;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  margin: 10px 0 18px;
}
.ref-section {
  border-top: 1px solid var(--border);
  padding-top: 8px;
  margin-top: 22px;
  scroll-margin-top: calc(var(--header-h) + 10px);
}
.ref-section h2 {
  font-size: 1.45rem;
  margin: 10px 0 6px;
}
.ref-section > p {
  max-width: 72ch;
}
.ref-entry {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 10px 16px 12px;
  margin: 12px 0;
}
.ref-entry h3 {
  margin: 2px 0 4px;
  font-size: 1.08rem;
}
.ref-entry h3 code {
  color: var(--t-keyword);
}
.ref-entry .en {
  font-weight: 500;
  color: var(--fg-muted);
  font-size: 0.92rem;
}
.ref-entry .en code {
  color: var(--fg-muted);
}
.ref-entry p {
  margin: 4px 0;
}
.arg {
  font-size: 0.93rem;
  color: var(--fg-muted);
}
.ref-example {
  margin: 10px 0 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--code-bg);
}
.ref-example pre {
  margin: 0;
  padding: 10px 14px;
  overflow-x: auto;
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1.55;
}
.ref-example figcaption {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 10px;
  border-top: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-sunk) 50%, var(--code-bg));
  font-size: 0.88rem;
}
.ref-example figcaption .btn {
  margin-left: auto;
}
.ref-example .note {
  color: var(--error);
  font-weight: 600;
}
table.limits,
table.shortcuts {
  border-collapse: collapse;
  width: 100%;
  margin: 8px 0;
  font-size: 0.95rem;
}
table.limits th,
table.limits td,
table.shortcuts th,
table.shortcuts td {
  text-align: left;
  padding: 7px 10px;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}
table.limits thead th {
  color: var(--fg-muted);
  font-size: 0.85rem;
}
table.limits tbody th,
table.shortcuts th {
  font-weight: 500;
}
table.shortcuts th {
  width: 40%;
}

/* ---- Dialogs and toast --------------------------------------------------- */

.dialog {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-elev);
  color: var(--fg);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
  padding: 18px 22px;
  width: min(560px, calc(100vw - 24px));
}
.dialog::backdrop {
  background: rgba(10, 20, 15, 0.45);
}
.dialog h2 {
  margin: 0 0 8px;
  font-size: 1.25rem;
}
.dialog form {
  margin: 0;
}
.dialog-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  margin-top: 12px;
}
.dialog > form:last-child {
  display: flex;
  justify-content: flex-end;
  margin-top: 12px;
}
.share-field {
  width: 100%;
  font: inherit;
  font-family: var(--mono);
  font-size: 0.85rem;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--code-bg);
  color: var(--fg);
  margin-top: 4px;
}
.hint {
  color: var(--fg-muted);
  font-size: 0.9rem;
  min-height: 1.4em;
  margin: 6px 0 0;
}

.toast {
  position: fixed;
  left: 50%;
  bottom: max(16px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: min(640px, calc(100vw - 24px));
  padding: 8px 8px 8px 16px;
  border-radius: 999px;
  background: var(--fg);
  color: var(--bg);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
  font-size: 0.93rem;
}
.toast .link {
  color: var(--bg);
}
.toast .icon-btn {
  color: var(--bg);
}
.toast .icon-btn:hover {
  background: color-mix(in srgb, var(--bg) 18%, transparent);
  border-color: transparent;
}

/* ---- Small screens ------------------------------------------------------- */

@media (max-width: 900px) {
  .studio {
    height: auto;
    min-height: 0;
  }
  .workspace {
    grid-template-columns: 1fr;
  }
  .editor {
    min-height: 260px;
    max-height: 48vh;
  }
  .viewhost {
    min-height: 58vh;
  }
}

@media (max-width: 640px) {
  .topbar {
    gap: 6px 10px;
    padding-top: 6px;
    padding-bottom: 6px;
  }
  .nav {
    order: 5;
    width: 100%;
    justify-content: space-between;
  }
  .nav-link {
    padding: 5px 10px;
    font-size: 0.9rem;
  }
  .mode-switch {
    margin-left: auto;
  }
  .studio {
    padding: 8px;
  }
  .pane {
    padding: 8px;
  }
  .toolbar .tool {
    flex: 1 1 auto;
    padding: 6px 8px;
  }
  .speed {
    width: 100%;
    margin-left: 0;
  }
  .speed input {
    flex: 1;
  }
  .filebar .tool .tool-label {
    font-size: 0.82rem;
  }
  .challenge-panel {
    flex-direction: column;
  }
  .challenge-target {
    width: 100%;
    height: 130px;
  }
  .view-hint {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    scroll-behavior: auto !important;
    transition: none !important;
  }
}

tool_use_result.content:
/* Logomocja — warm paper in light mode, deep green slate in dark mode. */

:root {
  color-scheme: light;
  --bg: #f6f1e6;
  --bg-elev: #fffdf8;
  --bg-sunk: #efe8d9;
  --fg: #1d2b24;
  --fg-muted: #5c6a62;
  --border: #ddd3bf;
  --accent: #16866a;
  --accent-strong: #0f6b54;
  --accent-fg: #ffffff;
  --accent-soft: #d8efe6;
  --warm: #c1763d;
  --warm-soft: #f6e3d2;
  --error: #b3261e;
  --error-soft: #fbe3e0;
  --ok: #1f7a4d;
  --ok-soft: #dcf2e5;
  --focus: #2b6fb3;
  --shadow: 0 1px 2px rgba(60, 50, 30, 0.08), 0 4px 16px rgba(60, 50, 30, 0.06);

  --code-bg: #fffdf8;
  --code-fg: #1d2b24;
  --code-gutter: #9a9384;
  --current-line: rgba(22, 134, 106, 0.14);
  --error-line: rgba(179, 38, 30, 0.08);
  --t-comment: #8a8270;
  --t-string: #a14d12;
  --t-number: #b0522c;
  --t-keyword: #0f6b54;
  --t-value: #7b3fa0;
  --t-proc: #2b5fa3;
  --t-name: #1d2b24;
  --t-bracket: #8a6d1d;
  --t-op: #5c6a62;

  --canvas-bg: #fffdf8;
  --canvas-grid: rgba(60, 50, 30, 0.07);
  --canvas-axis: rgba(60, 50, 30, 0.28);
  --canvas-origin: #c1763d;
  --canvas-turtle: #1d2b24;

  --radius: 12px;
  --radius-sm: 8px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", Ubuntu, Cantarell, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "Cascadia Code", "JetBrains Mono", "SF Mono", Menlo, Consolas, "DejaVu Sans Mono", "Liberation Mono", monospace;
  --header-h: 56px;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --bg: #101a17;
    --bg-elev: #17241f;
    --bg-sunk: #0c1412;
    --fg: #e5eee9;
    --fg-muted: #9db0a6;
    --border: #2b3d36;
    --accent: #3cc39c;
    --accent-strong: #5fd6b2;
    --accent-fg: #06261d;
    --accent-soft: #173a30;
    --warm: #e8a46a;
    --warm-soft: #3a2a1c;
    --error: #ff8a80;
    --error-soft: #3d1f1c;
    --ok: #6fdc9f;
    --ok-soft: #173326;
    --focus: #7fb5ff;
    --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 6px 20px rgba(0, 0, 0, 0.25);
    --code-bg: #131f1b;
    --code-fg: #e5eee9;
    --code-gutter: #61766d;
    --current-line: rgba(60, 195, 156, 0.16);
    --error-line: rgba(255, 138, 128, 0.1);
    --t-comment: #7d8f86;
    --t-string: #f0b37e;
    --t-number: #f49b74;
    --t-keyword: #5fd6b2;
    --t-value: #d2a8ff;
    --t-proc: #8cb8ff;
    --t-name: #e5eee9;
    --t-bracket: #e3c56b;
    --t-op: #9db0a6;
    --canvas-bg: #131f1b;
    --canvas-grid: rgba(220, 240, 230, 0.06);
    --canvas-axis: rgba(220, 240, 230, 0.25);
    --canvas-origin: #e8a46a;
    --canvas-turtle: #e5eee9;
  }
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #101a17;
  --bg-elev: #17241f;
  --bg-sunk: #0c1412;
  --fg: #e5eee9;
  --fg-muted: #9db0a6;
  --border: #2b3d36;
  --accent: #3cc39c;
  --accent-strong: #5fd6b2;
  --accent-fg: #06261d;
  --accent-soft: #173a30;
  --warm: #e8a46a;
  --warm-soft: #3a2a1c;
  --error: #ff8a80;
  --error-soft: #3d1f1c;
  --ok: #6fdc9f;
  --ok-soft: #173326;
  --focus: #7fb5ff;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 6px 20px rgba(0, 0, 0, 0.25);
  --code-bg: #131f1b;
  --code-fg: #e5eee9;
  --code-gutter: #61766d;
  --current-line: rgba(60, 195, 156, 0.16);
  --error-line: rgba(255, 138, 128, 0.1);
  --t-comment: #7d8f86;
  --t-string: #f0b37e;
  --t-number: #f49b74;
  --t-keyword: #5fd6b2;
  --t-value: #d2a8ff;
  --t-proc: #8cb8ff;
  --t-name: #e5eee9;
  --t-bracket: #e3c56b;
  --t-op: #9db0a6;
  --canvas-bg: #131f1b;
  --canvas-grid: rgba(220, 240, 230, 0.06);
  --canvas-axis: rgba(220, 240, 230, 0.25);
  --canvas-origin: #e8a46a;
  --canvas-turtle: #e5eee9;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  -webkit-text-size-adjust: 100%;
}

body {
  min-height: 100dvh;
}

[hidden] {
  display: none !important;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -60px;
  z-index: 100;
  background: var(--accent);
  color: var(--accent-fg);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  text-decoration: none;
  font-weight: 600;
}
.skip-link:focus {
  top: 8px;
}

a {
  color: var(--accent-strong);
}

kbd {
  font-family: var(--mono);
  font-size: 0.85em;
  background: var(--bg-sunk);
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-radius: 6px;
  padding: 1px 6px;
  white-space: nowrap;
}

code {
  font-family: var(--mono);
  font-size: 0.92em;
}

.icon {
  width: 20px;
  height: 20px;
  flex: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
}
.icon path[fill] {
  stroke: none;
}

/* ---- Layout ------------------------------------------------------------ */

.app {
  min-height: 100dvh;
  display: grid;
  grid-template-rows: auto 1fr;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 12px 18px;
  flex-wrap: wrap;
  padding: 8px max(16px, env(safe-area-inset-right)) 8px max(16px, env(safe-area-inset-left));
  min-height: var(--header-h);
  background: color-mix(in srgb, var(--bg) 88%, transparent);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  font-size: 1.15rem;
  letter-spacing: -0.01em;
  color: var(--fg);
  text-decoration: none;
}
.brand-mark {
  display: inline-grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 9px;
  background: var(--accent);
  color: var(--accent-fg);
  font-size: 14px;
  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.15);
}

.nav {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}
.nav-link {
  padding: 6px 12px;
  border-radius: 999px;
  color: var(--fg-muted);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
}
.nav-link:hover {
  color: var(--fg);
  background: var(--bg-sunk);
}
.nav-link[aria-current="page"] {
  color: var(--accent-strong);
  background: var(--accent-soft);
}

.mode-switch {
  display: inline-flex;
  padding: 3px;
  border-radius: 999px;
  background: var(--bg-sunk);
  border: 1px solid var(--border);
  margin-left: auto;
}
.mode-btn {
  font: inherit;
  font-weight: 700;
  font-size: 0.9rem;
  border: 0;
  background: transparent;
  color: var(--fg-muted);
  padding: 4px 14px;
  border-radius: 999px;
  cursor: pointer;
  min-height: 32px;
}
.mode-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--accent-fg);
  box-shadow: var(--shadow);
}
.mode-btn:disabled {
  cursor: not-allowed;
  opacity: 0.75;
}

.topbar-actions {
  display: flex;
  gap: 4px;
}

.icon-btn {
  display: inline-grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--fg);
  cursor: pointer;
}
.icon-btn:hover {
  background: var(--bg-sunk);
  border-color: var(--border);
}
.icon-btn.small {
  width: 30px;
  height: 30px;
}

main {
  min-width: 0;
}

/* ---- Buttons ------------------------------------------------------------ */

.btn,
.tool {
  font: inherit;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--bg-elev);
  color: var(--fg);
  cursor: pointer;
  font-weight: 600;
  white-space: nowrap;
  min-height: 38px;
  padding: 6px 12px;
}
.btn:hover,
.tool:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
  background: color-mix(in srgb, var(--accent-soft) 45%, var(--bg-elev));
}
.btn.primary,
.tool.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-fg);
}
.btn.primary:hover,
.tool.primary:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}
.btn.small {
  min-height: 30px;
  padding: 3px 10px;
  font-size: 0.9rem;
}
.tool:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.tool.small {
  min-height: 32px;
  padding: 4px 10px;
  font-size: 0.88rem;
  font-weight: 600;
}
.tool.small .icon {
  width: 17px;
  height: 17px;
}
.link {
  font: inherit;
  background: none;
  border: 0;
  padding: 0 2px;
  color: var(--accent-strong);
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
  font-weight: 600;
}

/* ---- Studio ------------------------------------------------------------- */

.studio {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px max(12px, env(safe-area-inset-right)) 12px max(12px, env(safe-area-inset-left));
  height: calc(100dvh - var(--header-h));
  min-height: 560px;
}

.workspace {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(340px, 1fr) minmax(0, 1.35fr);
  gap: 12px;
}

.pane {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 10px;
}

.toolbar,
.filebar {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}
.filebar {
  padding-top: 2px;
}

.speed {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  font-size: 0.9rem;
  color: var(--fg-muted);
  font-weight: 600;
}
.speed input {
  width: 110px;
  accent-color: var(--accent);
}

/* ---- Editor ------------------------------------------------------------- */

.editor {
  --line: 1.6em;
  position: relative;
  flex: 1;
  min-height: 180px;
  display: flex;
  font-family: var(--mono);
  font-size: 14.5px;
  line-height: var(--line);
  background: var(--code-bg);
  color: var(--code-fg);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  overflow: hidden;
}
.editor:focus-within {
  outline: 3px solid var(--focus);
  outline-offset: 1px;
}
.editor-gutter {
  flex: none;
  min-width: 3.4em;
  padding: 10px 8px 10px 4px;
  text-align: right;
  color: var(--code-gutter);
  background: color-mix(in srgb, var(--bg-sunk) 55%, var(--code-bg));
  border-right: 1px solid var(--border);
  user-select: none;
  will-change: transform;
}
.editor-gutter .line {
  height: var(--line);
  position: relative;
  padding-left: 1.2em;
}
.editor-gutter .line.is-current {
  color: var(--accent-strong);
  font-weight: 700;
}
.editor-gutter .line.is-error {
  color: var(--error);
  font-weight: 700;
}
.gutter-mark {
  position: absolute;
  left: 2px;
  font-size: 0.8em;
}
.editor-scroller {
  position: relative;
  flex: 1;
  min-width: 0;
  overflow: hidden;
}
.editor-code,
.editor-input {
  margin: 0;
  padding: 10px 14px 40px;
  font: inherit;
  line-height: inherit;
  white-space: pre;
  tab-size: 2;
  letter-spacing: 0;
  word-spacing: 0;
}
.editor-code {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  pointer-events: none;
  will-change: transform;
}
.editor-code .line {
  height: var(--line);
  margin: 0 -14px;
  padding: 0 14px;
}
.editor-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  resize: none;
  border: 0;
  outline: none;
  background: transparent;
  color: transparent;
  caret-color: var(--fg);
  overflow: auto;
  -webkit-text-fill-color: transparent;
}
.editor-input::selection {
  background: color-mix(in srgb, var(--focus) 30%, transparent);
  -webkit-text-fill-color: transparent;
}
.line.is-current {
  background: var(--current-line);
}
.line.is-error {
  background: var(--error-line);
}
.t-comment {
  color: var(--t-comment);
  font-style: italic;
}
.t-string {
  color: var(--t-string);
}
.t-number {
  color: var(--t-number);
}
.t-keyword {
  color: var(--t-keyword);
  font-weight: 700;
}
.t-value {
  color: var(--t-value);
  font-weight: 600;
}
.t-proc {
  color: var(--t-proc);
  font-weight: 600;
}
.t-name {
  color: var(--t-name);
}
.t-bracket {
  color: var(--t-bracket);
  font-weight: 700;
}
.t-paren,
.t-op {
  color: var(--t-op);
}
.t-error {
  text-decoration: wavy underline var(--error);
  text-decoration-skip-ink: none;
  text-underline-offset: 4px;
  background: color-mix(in srgb, var(--error) 14%, transparent);
  border-radius: 2px;
}
.inline-error {
  color: var(--error);
  font-family: var(--font);
  font-size: 0.86em;
  font-weight: 600;
}

.error-box {
  border-radius: var(--radius-sm);
  background: var(--error-soft);
  color: var(--fg);
  border: 1px solid color-mix(in srgb, var(--error) 40%, transparent);
  padding: 8px 12px;
  font-size: 0.93rem;
}
.error-box strong {
  color: var(--error);
}

/* ---- View --------------------------------------------------------------- */

.view-pane {
  padding: 0;
  overflow: hidden;
  gap: 0;
}
.viewhost {
  position: relative;
  flex: 1;
  min-height: 260px;
  display: flex;
  flex-direction: column;
}
.stage {
  position: relative;
  flex: 1;
  min-height: 0;
}
.view2d,
.view3d {
  position: absolute;
  inset: 0;
}
.view-canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
  background: var(--canvas-bg);
}
.view-canvas:active {
  cursor: grabbing;
}
.view-canvas:focus-visible {
  outline-offset: -4px;
}
.view-controls {
  position: absolute;
  top: 10px;
  right: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  z-index: 2;
}
.view-controls .tool {
  width: 38px;
  height: 38px;
  padding: 0;
  box-shadow: var(--shadow);
}
.view-hint {
  position: absolute;
  left: 12px;
  bottom: 8px;
  margin: 0;
  max-width: calc(100% - 24px);
  font-size: 0.78rem;
  color: var(--fg-muted);
  pointer-events: none;
}
.notice {
  margin: 10px;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  background: var(--warm-soft);
  border: 1px solid color-mix(in srgb, var(--warm) 45%, transparent);
  font-size: 0.92rem;
  z-index: 1;
}
.statusbar {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 4px 12px;
  padding: 8px 12px;
  border-top: 1px solid var(--border);
  font-size: 0.88rem;
  color: var(--fg-muted);
  background: var(--bg-elev);
}
.status-text {
  font-weight: 700;
  color: var(--fg);
}

/* ---- Challenge panel ---------------------------------------------------- */

.challenge-panel {
  display: flex;
  gap: 14px;
  align-items: stretch;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-left: 5px solid var(--warm);
  border-radius: var(--radius);
  padding: 10px 14px;
  box-shadow: var(--shadow);
}
.challenge-panel h2 {
  margin: 0 0 2px;
  font-size: 1.1rem;
}
.challenge-task {
  margin: 0 0 4px;
  font-weight: 600;
}
.challenge-panel details {
  font-size: 0.92rem;
  color: var(--fg-muted);
}
.challenge-panel details p {
  margin: 4px 0;
}
.challenge-panel summary {
  cursor: pointer;
  font-weight: 600;
}
.challenge-info {
  flex: 1;
  min-width: 0;
}
.challenge-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}
.challenge-target {
  position: relative;
  flex: none;
  width: 150px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  border: 1px solid var(--border);
  background: var(--canvas-bg);
}
.challenge-target .thumb {
  width: 100%;
  height: 100%;
  min-height: 110px;
}
.challenge-target .caption {
  position: absolute;
  left: 6px;
  top: 4px;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--fg-muted);
}
.challenge-result {
  margin: 8px 0 0;
  font-weight: 600;
}
.challenge-result:empty {
  display: none;
}
.challenge-result.is-pass {
  color: var(--ok);
  background: var(--ok-soft);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
}
.challenge-result.is-fail {
  color: var(--error);
  background: var(--error-soft);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
}

/* ---- Pages -------------------------------------------------------------- */

.page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 24px max(16px, env(safe-area-inset-right)) 64px max(16px, env(safe-area-inset-left));
}
.page h1 {
  font-size: clamp(1.7rem, 3vw, 2.3rem);
  letter-spacing: -0.02em;
  margin: 8px 0 6px;
}
.lead {
  color: var(--fg-muted);
  max-width: 70ch;
  font-size: 1.05rem;
}

.card-grid {
  list-style: none;
  padding: 0;
  margin: 12px 0 28px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 14px;
}
.card {
  display: flex;
  flex-direction: column;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}
.card .thumb {
  display: block;
  width: 100%;
  height: 160px;
  background: var(--canvas-bg);
  border-bottom: 1px solid var(--border);
}
.card-body {
  padding: 10px 14px 4px;
  flex: 1;
}
.card-body h3 {
  margin: 0 0 4px;
  font-size: 1.05rem;
}
.card-body p {
  margin: 0 0 6px;
  color: var(--fg-muted);
  font-size: 0.93rem;
}
.card > .btn {
  margin: 4px 14px 14px;
}
.badge {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  padding: 1px 7px;
  border-radius: 999px;
  vertical-align: middle;
  background: var(--accent-soft);
  color: var(--accent-strong);
}
.challenge-card .state {
  font-weight: 700;
  color: var(--fg-muted);
}
.challenge-card .state.ok {
  color: var(--ok);
}
.challenge-card.is-passed {
  border-color: color-mix(in srgb, var(--ok) 45%, var(--border));
}
.challenge-progress {
  font-weight: 700;
  display: inline-block;
  background: var(--warm-soft);
  padding: 4px 12px;
  border-radius: 999px;
}

/* Reference */

.reference {
  max-width: 900px;
}
.toc ul {
  list-style: none;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  margin: 10px 0 18px;
}
.ref-section {
  border-top: 1px solid var(--border);
  padding-top: 8px;
  margin-top: 22px;
  scroll-margin-top: calc(var(--header-h) + 10px);
}
.ref-section h2 {
  font-size: 1.45rem;
  margin: 10px 0 6px;
}
.ref-section > p {
  max-width: 72ch;
}
.ref-entry {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 10px 16px 12px;
  margin: 12px 0;
}
.ref-entry h3 {
  margin: 2px 0 4px;
  font-size: 1.08rem;
}
.ref-entry h3 code {
  color: var(--t-keyword);
}
.ref-entry .en {
  font-weight: 500;
  color: var(--fg-muted);
  font-size: 0.92rem;
}
.ref-entry .en code {
  color: var(--fg-muted);
}
.ref-entry p {
  margin: 4px 0;
}
.arg {
  font-size: 0.93rem;
  color: var(--fg-muted);
}
.ref-example {
  margin: 10px 0 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--code-bg);
}
.ref-example pre {
  margin: 0;
  padding: 10px 14px;
  overflow-x: auto;
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1.55;
}
.ref-example figcaption {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 10px;
  border-top: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-sunk) 50%, var(--code-bg));
  font-size: 0.88rem;
}
.ref-example figcaption .btn {
  margin-left: auto;
}
.ref-example .note {
  color: var(--error);
  font-weight: 600;
}
table.limits,
table.shortcuts {
  border-collapse: collapse;
  width: 100%;
  margin: 8px 0;
  font-size: 0.95rem;
}
table.limits th,
table.limits td,
table.shortcuts th,
table.shortcuts td {
  text-align: left;
  padding: 7px 10px;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}
table.limits thead th {
  color: var(--fg-muted);
  font-size: 0.85rem;
}
table.limits tbody th,
table.shortcuts th {
  font-weight: 500;
}
table.shortcuts th {
  width: 40%;
}

/* ---- Dialogs and toast --------------------------------------------------- */

.dialog {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-elev);
  color: var(--fg);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
  padding: 18px 22px;
  width: min(560px, calc(100vw - 24px));
}
.dialog::backdrop {
  background: rgba(10, 20, 15, 0.45);
}
.dialog h2 {
  margin: 0 0 8px;
  font-size: 1.25rem;
}
.dialog form {
  margin: 0;
}
.dialog-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  margin-top: 12px;
}
.dialog > form:last-child {
  display: flex;
  justify-content: flex-end;
  margin-top: 12px;
}
.share-field {
  width: 100%;
  font: inherit;
  font-family: var(--mono);
  font-size: 0.85rem;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--code-bg);
  color: var(--fg);
  margin-top: 4px;
}
.hint {
  color: var(--fg-muted);
  font-size: 0.9rem;
  min-height: 1.4em;
  margin: 6px 0 0;
}

.toast {
  position: fixed;
  left: 50%;
  bottom: max(16px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: min(640px, calc(100vw - 24px));
  padding: 8px 8px 8px 16px;
  border-radius: 999px;
  background: var(--fg);
  color: var(--bg);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
  font-size: 0.93rem;
}
.toast .link {
  color: var(--bg);
}
.toast .icon-btn {
  color: var(--bg);
}
.toast .icon-btn:hover {
  background: color-mix(in srgb, var(--bg) 18%, transparent);
  border-color: transparent;
}

/* ---- Small screens ------------------------------------------------------- */

@media (max-width: 900px) {
  .studio {
    height: auto;
    min-height: 0;
  }
  .workspace {
    grid-template-columns: 1fr;
  }
  .editor {
    min-height: 260px;
    max-height: 48vh;
  }
  .viewhost {
    min-height: 58vh;
  }
}

@media (max-width: 640px) {
  .topbar {
    gap: 6px 10px;
    padding-top: 6px;
    padding-bottom: 6px;
  }
  .nav {
    order: 5;
    width: 100%;
    justify-content: space-between;
  }
  .nav-link {
    padding: 5px 10px;
    font-size: 0.9rem;
  }
  .mode-switch {
    margin-left: auto;
  }
  .studio {
    padding: 8px;
  }
  .pane {
    padding: 8px;
  }
  .toolbar .tool {
    flex: 1 1 auto;
    padding: 6px 8px;
  }
  .speed {
    width: 100%;
    margin-left: 0;
  }
  .speed input {
    flex: 1;
  }
  .filebar .tool .tool-label {
    font-size: 0.82rem;
  }
  .challenge-panel {
    flex-direction: column;
  }
  .challenge-target {
    width: 100%;
    height: 130px;
  }
  .view-hint {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    scroll-behavior: auto !important;
    transition: none !important;
  }
}

