  clearTimeout(toastTimer);
  toast.hidden = false;
  toast.replaceChildren(
    h("span", {}, message),
    action && h("button", { type: "button", class: "link", onclick: () => (action.run(), (toast.hidden = true)) }, action.label),
    h("button", { type: "button", class: "icon-btn small", "aria-label": "Zamknij powiadomienie", onclick: () => (toast.hidden = true) }, icon(ICONS.close)),
  );
  toastTimer = setTimeout(() => (toast.hidden = true), 9000);
}
