import { version } from "../../package.json";
import { compile, run, type LogoError, type Mode, type RunResult } from "../lang";
import { createController, MAX_SPEED, SPEEDS, type Controller, type ControllerState, type FrameScheduler } from "../runner/controller";
import { h, icon, ICONS } from "./dom";
import { CHALLENGES, checkChallenge, type Challenge } from "../challenges";
import { EXAMPLES } from "../examples";
import { REFERENCE, type RefExample } from "../reference";
import { createEditor } from "./editor";
import { createStore } from "./storage";
import { decodeShare, encodeShare, isShareHash } from "./share";
import { thumbnailFor } from "./thumbnail";
import { createViewHost } from "./viewhost";

export type Route =
  | { page: "studio" }
  | { page: "examples" }
  | { page: "example"; id: string }
  | { page: "challenges" }
  | { page: "challenge"; id: string }
  | { page: "reference" };

export function parseRoute(hash: string): Route {
  const path = hash.replace(/^#\/?/, "");
  if (path === "przyklady") return { page: "examples" };
  if (path.startsWith("przyklady/")) return { page: "example", id: decodeURIComponent(path.slice(10)) };
  if (path === "wyzwania") return { page: "challenges" };
  if (path.startsWith("wyzwania/")) return { page: "challenge", id: decodeURIComponent(path.slice(9)) };
  if (path === "polecenia") return { page: "reference" };
  return { page: "studio" };
}

export interface AppEnv {
  scheduler?: FrameScheduler;
  storage?: Storage | null;
  /** Hand a file to the user (a browser download by default). */
  save?: (blob: Blob, filename: string) => void;
}

export function browserSave(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.rel = "noopener";
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

/** A file name from the program's first comment, e.g. "; Mój dom" → "moj-dom.logo". */
export function programFileName(source: string, mode: Mode) {
  const comment = /^\s*;\s*(.+)$/m.exec(source)?.[1] ?? "";
  const slug = comment
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/ł/g, "l")
    .replace(/Ł/g, "L")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40)
    .replace(/-+$/, "");
  return `${slug || `logomocja-${mode}`}.logo`;
}

