  function draftKey(m: Mode) {
    return `draft:${m}`;
  }

  /** The saved draft of a mode; a first visit starts from an example. */
  function draftOf(m: Mode) {
    return store.get(draftKey(m)) ?? EXAMPLES.find((e) => e.id === (m === "2d" ? "kwadrat" : "schody"))!.source;
  }

  let challenge: Challenge | null = null;
  /** Where the editor's text is saved: the mode's draft, or the open challenge's own program. */
  const bufferKey = () => (challenge ? `challenge:${challenge.id}` : draftKey(mode));

  function setSource(source: string) {
    editor.value = source;
    store.set(bufferKey(), source);
    controller.load(source, mode);
  }

  function setMode(next: Mode) {
    mode = next;
    store.set("mode", mode);
    for (const b of modeButtons) b.setAttribute("aria-pressed", String(b.dataset.mode === mode));
    viewHost.setMode(mode);
  }

  function enterChallenge(c: Challenge) {
    if (challenge?.id === c.id) return;
    store.set(bufferKey(), editor.value);
    challenge = c;
    setMode(c.mode);
    editor.value = store.get(bufferKey()) ?? `; Wyzwanie: ${c.title}\n; ${c.task}\n\n`;
    controller.load(editor.value, mode);
    controller.reset();
    for (const b of modeButtons) {
      b.disabled = true;
      b.title = "Tryb ustala wyzwanie";
    }
    challengeTitle.textContent = `Wyzwanie: ${c.title}`;
    challengeTask.textContent = c.task;
    challengeHint.textContent = c.hint;
    const thumb = thumbnailFor(c.solution, c.mode, `Wzór do narysowania: ${c.title}`);
    challengeTarget.replaceChildren(thumb.canvas, h("span", { class: "caption" }, "Wzór"));
    const passed = progress()[c.id]?.passed;
    challengeResult.textContent = passed ? "To wyzwanie jest już zaliczone. Możesz spróbować innego rozwiązania." : "";
    challengeResult.className = "challenge-result";
    challengePanel.hidden = false;
    updateRestore();
  }

  function leaveChallenge() {
    if (!challenge) return;
    store.set(bufferKey(), editor.value);
    challenge = null;
    challengePanel.hidden = true;
    for (const b of modeButtons) {
      b.disabled = false;
      b.title = "";
    }
    editor.value = draftOf(mode);
    controller.load(editor.value, mode);
    controller.reset();
    updateRestore();
  }

  function checkCurrent() {
    if (!challenge) return;
    const result = checkChallenge(challenge, editor.value);
    controller.reset();
    execute("finish");
    if (!viewHost.userMoved) viewHost.fit();
    if (result.pass) {
      store.setJSON("progress", { ...progress(), [challenge.id]: { passed: true, at: new Date().toISOString() } });
      challengeResult.textContent = result.reason;
    } else {
      challengeResult.textContent = `Nie zaliczone: ${result.reason}`;
    }
    challengeResult.className = `challenge-result ${result.pass ? "is-pass" : "is-fail"}`;
  }

  const isExampleSource = (src: string) => EXAMPLES.some((e) => e.source === src);

  /**
   * Put a new program into a mode's editor. An edited draft that would be lost is kept
   * as that mode's "previous draft" and can be restored.
   */
  function replaceDraft(source: string, m: Mode, what: string | null) {
    switchMode(m);
    const old = editor.value;
    const keep = old.trim() !== "" && old !== source && !isExampleSource(old);
    if (keep) store.setJSON(`stash:${m}`, { source: old, at: new Date().toISOString() });
    setSource(source);
    updateRestore();
    if (what === null) return;
    if (keep) showToast(`${what} Twój poprzedni szkic jest bezpieczny.`, { label: "Przywróć szkic", run: restoreStash });
    else showToast(what);
  }

  function restoreStash() {
    const stash = store.getJSON<{ source: string } | null>(`stash:${mode}`, null);
    if (!stash) return;
    const current = editor.value;
    if (current.trim() !== "" && !isExampleSource(current)) store.setJSON(`stash:${mode}`, { source: current, at: new Date().toISOString() });
    else store.remove(`stash:${mode}`);
    setSource(stash.source);
    controller.reset();
    updateRestore();
    editor.textarea.focus();
  }

  function updateRestore() {
    restoreBtn.hidden = !!challenge || !store.get(`stash:${mode}`);
  }

  function openExample(id: string) {
    const e = EXAMPLES.find((x) => x.id === id);
    if (!e) return;
    replaceDraft(e.source, e.mode, `Wczytano przykład „${e.name}”.`);
    go("#/");
    controller.reset();
    execute("finish");
    viewHost.fit();
  }

  function go(hash: string) {
    const fromExampleLink = parseRoute(location.hash).page === "example";
    if (location.hash !== hash) history[fromExampleLink ? "replaceState" : "pushState"](null, "", hash);
    showRoute(parseRoute(hash));
  }

  const pages: Record<Route["page"], HTMLElement> = {
    studio,
    examples: examplesPage,
    example: studio,
    challenges: challengesPage,
    challenge: studio,
    reference: referencePage,
  };

  function showRoute(route: Route) {
    if (route.page === "example") {
      if (EXAMPLES.some((e) => e.id === route.id)) return openExample(route.id);
      history.replaceState(null, "", "#/przyklady");
      return showRoute({ page: "examples" });
    }
    if (route.page === "challenge") {
      const c = CHALLENGES.find((x) => x.id === route.id);
      if (!c) {
        history.replaceState(null, "", "#/wyzwania");
        return showRoute({ page: "challenges" });
      }
      enterChallenge(c);
    } else if (route.page === "studio") leaveChallenge();
    if (route.page === "challenges") renderChallenges();
    const page = pages[route.page];
    for (const p of new Set(Object.values(pages))) p.hidden = p !== page;
    for (const a of navLinks) {
      const section = route.page === "challenge" ? "challenges" : route.page;
      if (a.dataset.route === section) a.setAttribute("aria-current", "page");
      else a.removeAttribute("aria-current");
    }
    if (route.page === "examples") requestAnimationFrame(() => exampleThumbs.forEach((r) => r()));
    if (route.page === "studio") viewHost.show({ segments: controller.state.segments, turtle: controller.state.turtle });
  }

  const onHash = () => {
    if (isShareHash(location.hash)) void openPermalink(location.hash);
    else {
      showRoute(parseRoute(location.hash));
      focusPage();
    }
  };

  /** After navigating, move focus to the new page's heading so keyboard and screen-reader users start there. */
  function focusPage() {
    const page = [examplesPage, challengesPage, referencePage].find((p) => !p.hidden);
    const heading = page?.querySelector<HTMLElement>("h1");
    if (!heading) return;
    heading.tabIndex = -1;
    heading.focus({ preventScroll: true });
    window.scrollTo?.({ top: 0 });
  }
  window.addEventListener("hashchange", onHash);

  function switchMode(next: Mode) {
    leaveChallenge();
    if (next === mode) return;
    store.set(draftKey(mode), editor.value);
    setMode(next);
    editor.value = draftOf(mode);
    controller.load(editor.value, mode);
    updateRestore();
  }

  editor.onInput((value) => {
    store.set(bufferKey(), value);
    controller.load(value, mode);
    clearTimeout(lintTimer);
    lintTimer = setTimeout(() => {
      lint = compile(editor.value, mode).error;
      render(controller.state);
    }, 350);
    render(controller.state);
  });

  let lastStatus = "";
  const unsubscribe = controller.subscribe((s) => render(s));

  function render(s: ControllerState) {
    const runError = s.error && ranSource === editor.value ? s.error : null;
    const shown = runError ?? (ranSource === editor.value ? null : lint);
    editor.setMarks(s.status === "running" || s.status === "paused" ? s.current : null, shown);
    // While animating slowly, let the turtle glide through each command's time slot.
    const slot = 1000 / SPEEDS[s.speed - 1];
    viewHost.show({ segments: s.segments, turtle: s.turtle }, s.status === "running" && slot >= 30 ? { duration: Math.min(slot * 0.85, 650) } : undefined);
    pauseBtn.querySelector(".tool-label")!.textContent = s.status === "paused" ? "Wznów" : "Pauza";
    pauseBtn.setAttribute("aria-label", s.status === "paused" ? "Wznów" : "Pauza");
    pauseBtn.replaceChild(icon(s.status === "paused" ? ICONS.play : ICONS.pause, true), pauseBtn.querySelector("svg")!);
    pauseBtn.disabled = !(s.status === "running" || s.status === "paused");
    const text = STATUS_TEXT[s.status];
    if (text !== lastStatus) {
      statusText.textContent = text;
      lastStatus = text;
    }
    statusDetail.textContent = describeTurtle(s);
    if (shown) {
      errorBox.hidden = false;
      // A run's error is announced at once; the live check while typing stays quiet.
      if (runError) errorBox.setAttribute("role", "alert");
      else errorBox.removeAttribute("role");
      errorBox.replaceChildren(
        h("strong", {}, `Wiersz ${shown.line}, kolumna ${shown.column}: `),
        shown.message,
        " ",
        h("button", { type: "button", class: "link", onclick: () => editor.focusAt(shown.line, shown.column) }, "Pokaż w programie"),
      );
    } else {
      errorBox.hidden = true;
      errorBox.replaceChildren();
    }
    const ended = (s.status === "done" || s.status === "error") && prevStatus !== s.status;
    if (ended && !viewHost.userMoved) viewHost.fit();
    prevStatus = s.status;
  }
  let prevStatus: ControllerState["status"] | null = null;

  function describeTurtle(s: ControllerState) {
    const f = (n: number) => (Math.round(n * 10) / 10).toLocaleString("pl-PL");
    const p = s.turtle.pos;
    const where = mode === "2d" ? `x ${f(p[0])}, y ${f(p[1])}` : `x ${f(p[0])}, y ${f(p[1])}, z ${f(p[2])}`;
    const n = s.segments.length;
    return `${n} ${n === 1 ? "odcinek" : n % 10 >= 2 && n % 10 <= 4 && !(n % 100 >= 12 && n % 100 <= 14) ? "odcinki" : "odcinków"} · żółw: ${where}`;
  }

  async function open(source: string, m: Mode): Promise<RunResult> {
    go("#/");
    replaceDraft(source, m, null);
    toast.hidden = true;
    for (const d of root.querySelectorAll("dialog")) if (d.open) d.close();
    controller.reset();
    execute("finish");
    await viewHost.ready();
    viewHost.fit();
    await painted();
    const s = controller.state;
    return { segments: s.segments, error: s.error };
  }

  // ---- Start --------------------------------------------------------------
  viewHost.setMode(mode);
  editor.value = draftOf(mode);
  controller.load(editor.value, mode);
  render(controller.state);
  updateRestore();
  applyTheme();
  const firstRoute = parseRoute(location.hash);
  // Show the draft's drawing straight away (a permalink replaces it below).
  if (!isShareHash(location.hash)) {
    execute("finish");
    void viewHost.ready().then(() => viewHost.fit());
  }
  if (isShareHash(location.hash)) void openPermalink(location.hash);
  else showRoute(firstRoute);

  const app: App = {
    open,
    controller,
    destroy() {
      document.removeEventListener("keydown", onKey);
      window.removeEventListener("hashchange", onHash);
      systemScheme?.removeEventListener?.("change", onSystemScheme);
      clearTimeout(toastTimer);
      clearTimeout(lintTimer);
      unsubscribe();
      controller.reset();
      viewHost.destroy();
    },
  };
  const hook: LogomocjaHook = { version, run: (src, m) => run(src, m), open };
  (window as unknown as { logomocja: LogomocjaHook }).logomocja = hook;
  return app;
}

